Object.assign(window.TEM8_DICTIONARY, {"rome":{"media":{"uk":"media/uk/rome__gb_1.mp3","us":"media/us/rome__us_1.mp3"},"oxford":{"phon":"rəʊm","pos":"noun","senses":[{"en":"( saying ) used to say that a complicated task will take a long time and needs patience","cn":"罗马不是一天建成的；复杂的工作不会一蹴而就"},{"en":"( saying ) used to say that when you are in a foreign country, or a situation you are not familiar with, you should behave in the way that the people around you behave","cn":"入乡随俗"}]}},"round-the-clock":{"oxford":{"phon":"ˌraʊnd ðə ˈklɒk","pos":"adjective","senses":[{"en":"lasting or happening all day and night","cn":"日夜不停的；持续一整天的","ex":{"en":"round-the-clock nursing care","cn":"全天的护理"}}]},"media":{"uk":"media/uk/round_the_clock_1_gb_1.mp3","us":"media/us/round_the_clock_1_us_1.mp3"},"examples":[{"en":"round-the-clock nursing care","cn":"全天的护理"},{"en":"round-the-clock medical care 24","cn":"小时医护"}],"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]}},"routinely":{"media":{"uk":"media/uk/routinely__gb_1.mp3","us":"media/us/routinely__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"例行地;常规地;通常地","en":"If something is routinely done, it is done as a normal part of a job or process.","ex":{"en":"Vitamin K is routinely given in the first week of life to prevent bleeding.","cn":"出生后第一周通常要服用维生素K，以防止出血。"}},{"pos":"ADV 副词","cn":"惯常地;毫不意外地","en":"If something happens routinely, it happens repeatedly and is not surprising, unnatural, or new.","ex":{"en":"Any outside criticism is routinely dismissed as interference","cn":"任何来自外界的批评通常都被当作干涉而不予理睬。"}}]},"examples":[{"en":"Visitors are routinely checked as they enter the building.","cn":"来访者在进入大楼时都要接受例行检查。"},{"en":"This vaccine is already routinely used.","cn":"这种疫苗的使用已经常规化。"}],"oxford":{"phon":"ruːˈtiːnli","pos":"adverb","senses":[{"en":"as part of the way in which things are regularly done","cn":"例行地：作为定期做事的一部分","ex":{"en":"Visitors are routinely checked as they enter the building.","cn":"访客进入大楼时须经例行检查。"}}]}},"roar":{"media":{"uk":"media/uk/roar__gb_1.mp3","us":"media/us/roar__us_1.mp3"},"oxford":{"phon":"rɔː(r)","pos":"verb","senses":[{"en":"to make a very loud, deep sound","cn":"吼叫；咆哮","g":"[intransitive]","ex":{"en":"We heard a lion roar.","cn":"我们听见了狮子的吼声。"}},{"en":"to shout something very loudly","cn":"叫喊；大声地说","g":"[intransitive, transitive]","ex":{"en":"The crowd roared.","cn":"人群一片喧哗。"}},{"en":"to laugh very loudly","cn":"放声大笑","g":"[intransitive]","ex":{"en":"He looked so funny, we all roared.","cn":"他看上去那么滑稽，我们都哈哈大笑。"}},{"en":"to move very fast, making a lot of noise","cn":"呼啸而行；开得飞快","g":"[intransitive]","ex":{"en":"She put her foot down and the car roared away.","cn":"她踩下油门，车子呼啸而去。"}},{"en":"to burn brightly with a lot of flames, heat and noise","cn":"熊熊燃烧","g":"[intransitive]","ex":{"en":"A log fire was roaring in the hearth.","cn":"壁炉里的柴火正在熊熊燃烧。"}},{"en":"a loud deep sound made by an animal, especially a lion, or by somebody’s voice","cn":"咆哮；吼叫","ex":{"en":"His speech was greeted by a roar of applause.","cn":"他的讲话引来了雷鸣般的掌声。"},"pos":"noun"},{"en":"a loud continuous noise made by the wind or sea, or by a machine","cn":"（风或海的）呼啸声；（机器的）隆隆声","ex":{"en":"I could barely hear above the roar of traffic.","cn":"除了车辆的轰鸣声，我几乎什么也听不见。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"呼啸而过;轰鸣着疾驰","en":"If something, usually a vehicle, roars somewhere, it goes there very fast, making a loud noise.","ex":{"en":"A police car roared past","cn":"一辆警车呼啸而过。"}},{"pos":"VERB 动词","cn":"咆哮;轰鸣;发出巨响","en":"If something roars, it makes a very loud noise.","ex":{"en":"The engine roared, and the vehicle leapt forward","cn":"发动机轰鸣着，车子猛然冲出去。"}},{"pos":"VERB 动词","cn":"大笑;狂笑","en":"If someone roars with laughter, they laugh in a very noisy way.","ex":{"en":"Max threw back his head and roared with laughter.","cn":"马克斯仰头大笑起来。"}},{"pos":"VERB 动词","cn":"大吼;喊叫;吼叫","en":"If someone roars, they shout something in a very loud voice.","ex":{"en":"'I'll kill you for that,' he roared","cn":"“我会为此杀了你，”他大吼道。"}},{"pos":"VERB 动词","cn":"(狮子)吼叫，咆哮","en":"When a lion roars, it makes the loud sound that lions typically make.","ex":{"en":"The lion roared once, and sprang.","cn":"狮子大吼一声，跳了起来。"}}]},"examples":[{"en":"I could barely hear above the roar of traffic.","cn":"除了车辆的轰鸣声，我几乎什么也听不见。"},{"en":"He looked so funny, we all roared.","cn":"他看上去那么滑稽，我们都哈哈大笑。"}]},"roman":{"media":{"uk":"media/uk/roman__gb_1.mp3","us":"media/us/roman__us_1.mp3"},"oxford":{"phon":"ˈrəʊmən","pos":"adjective","senses":[{"en":"connected with ancient Rome or the Roman Empire","cn":"古罗马的；古罗马帝国的","ex":{"en":"a Roman road/temple/villa","cn":"古罗马的公路／庙宇／别墅"}},{"en":"connected with the modern city of Rome","cn":"罗马的；罗马城的"},{"en":"connected with the Roman Catholic Church","cn":"天主教的"},{"en":"used to describe ordinary printing type that does not lean forward","cn":"罗马体的；西文白正体的","ex":{"en":"Definitions in this dictionary are printed in roman type.","cn":"这本词典里的释义是用罗马体印刷的。"}},{"en":"a member of the ancient Roman republic or empire","cn":"古罗马人","g":"[countable]","pos":"noun"},{"en":"a person from the modern city of Rome","cn":"（现代的）罗马人，罗马市民","g":"[countable]","pos":"noun"},{"en":"the ordinary style of printing that uses small letters that do not lean forward","cn":"罗马体；西文白正体","g":"[uncountable]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"古罗马的;古罗马帝国的","en":"Roman means related to or connected with ancient Rome and its empire.","ex":{"en":"...the fall of the Roman Empire.","cn":"古罗马帝国的覆灭"}},{"pos":"ADJ 形容词","cn":"罗马的;罗马城的","en":"Roman means related to or connected with modern Rome.","ex":{"en":"...a Roman hotel room.","cn":"罗马的一个宾馆房间"}},{"pos":"N-UNCOUNT 不可数名词","cn":"罗马字体;正体字","en":"Roman is the most common style of printing in books and magazines. It consists of upright letters. This dictionary is printed in roman."}]},"examples":[{"en":"Definitions in this dictionary are printed in roman type.","cn":"这本词典里的释义是用罗马体印刷的。"},{"en":"a Roman road/temple/villa","cn":"古罗马的公路/庙宇/别墅"}]},"romantic":{"media":{"uk":"media/uk/romantic__gb_1.mp3","us":"media/us/romantic__us_1.mp3"},"oxford":{"phon":"rəʊˈmæntɪk","pos":"adjective","senses":[{"en":"connected with or about love or a sexual relationship","cn":"浪漫的；爱情的；情爱的","ex":{"en":"a romantic candlelit dinner","cn":"浪漫的烛光晚餐"}},{"en":"showing feelings of love","cn":"多情的；表达爱情的","ex":{"en":"Why don't you ever give me flowers? I wish you'd be more romantic.","cn":"你为什么从来不给我送花？我真希望你能浪漫一点。"}},{"en":"beautiful in a way that makes you think of love or feel strong emotions","cn":"浪漫的；富有情调的；美妙的","ex":{"en":"romantic music","cn":"富有情调的音乐"}},{"en":"having an attitude to life where imagination and the emotions are especially important; not looking at situations in a realistic way","cn":"富于幻想的；不切实际的","ex":{"en":"a romantic view of life","cn":"对于生活的不切实际的想法"}},{"en":"used to describe literature, music or art, especially of the nineteenth century, that is about strong feelings, imagination and a return to nature, rather than reason, order and intellectual ideas","cn":"浪漫主义的（尤用以描述 19 世纪的文学、音乐或艺术，以情感强烈、想象和回归自然为特征）","g":"[usually before noun]","ex":{"en":"the Romantic movement","cn":"浪漫主义运动"}},{"en":"a person who is emotional and has a lot of imagination, and who has ideas and hopes that may not be realistic","cn":"浪漫的人；耽于幻想的人","ex":{"en":"a hopeless romantic","cn":"不可救药的浪漫主义者"},"pos":"noun"},{"en":"a writer, a musician or an artist who writes, etc. in the style of Romanticism","cn":"浪漫主义作家（或音乐家、艺术家）","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）浪漫的，富于浪漫气息的，有情调的","en":"Someone who is romantic or does romantic things says and does things that make their wife, husband, girlfriend, or boyfriend feel special and loved.","ex":{"en":"When we're together, all he talks about is business. I wish he were more romantic","cn":"我们在一起的时候，他总是谈论生意。我希望他能更浪漫一点。"}},{"pos":"ADJ 形容词","cn":"性爱的;和性爱有关的","en":"Romantic means connected with sexual love.","ex":{"en":"...his early romantic experiences","cn":"他早期的性爱经历"}},{"pos":"ADJ 形容词","cn":"（戏剧、电影或故事）关于爱情的，浪漫的","en":"A romantic play, film, or story describes or represents a love affair.","ex":{"en":"It is a lovely romantic comedy, well worth seeing.","cn":"这是一部温馨的爱情喜剧，非常值得一看。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(观点等)不现实的，不切实际的，空想的","en":"If you say that someone has a romantic view or idea of something, you are critical of them because their view of it is unrealistic and they think that thing is better or more exciting than it really is.","ex":{"en":"He has a romantic view of rural society","cn":"他对农村的看法不切实际。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（事物）浪漫的，富有浪漫色彩的，充满浪漫气息的","en":"Something that is romantic is beautiful in a way that strongly affects your feelings.","ex":{"en":"Seacliff House is one of the most romantic ruins in Scotland.","cn":"海崖城堡是苏格兰最富有浪漫色彩的遗迹之一。"}},{"pos":"ADJ 形容词","cn":"浪漫主义的（描述18、19世纪注重抒发个人情感的艺术运动）","en":"Romantic means connected with the artistic movement of the eighteenth and nineteenth centuries which was concerned with the expression of the individual's feelings and emotions.","ex":{"en":"...the poems and prose of the English romantic poets.","cn":"英国浪漫主义诗人的诗歌和散文"}}]},"examples":[{"en":"Why don't you ever give me flowers? I wish you'd be more romantic.","cn":"你为什么从来不给我送花？我真希望你能浪漫一点。"},{"en":"When I was younger, I had romantic ideas of becoming a writer.","cn":"我年轻一些的时候幻想过要成为一名作家。"}]},"role":{"media":{"uk":"media/uk/role__gb_1.mp3","us":"media/us/role__us_1.mp3"},"oxford":{"phon":"rəʊl","pos":"noun","senses":[{"en":"an actor’s part in a play, film, etc.","cn":"（演员的）角色","lab":"British English","ex":{"en":"She has landed the lead role (= the most important one) in a new play.","cn":"她在新剧中担任主角。"}},{"en":"the function or position that somebody has or is expected to have in an organization, in society or in a relationship","cn":"职能；地位；角色","ex":{"en":"the changing role of women","cn":"妇女角色的转变"}},{"en":"the degree to which somebody/something is involved in a situation or an activity and the effect that they have on it","cn":"影响程度；作用","ex":{"en":"A cup of tea often serves an important social role.","cn":"一杯茶通常起着重要的社交作用。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"作用;地位;职位;角色","en":"If you have a role in a situation or in society, you have a particular position and function in it.","ex":{"en":"...the drug's role in preventing more serious effects of infection","cn":"这种药物在防止感染加重方面的作用"}},{"pos":"N-COUNT 可数名词","cn":"(电影、戏剧或歌剧中的)角色","en":"A role is one of the characters that an actor or singer can play in a film, play, or opera.","ex":{"en":"She has just landed the lead role in The Young Vic's latest production","cn":"她刚刚获得在小维克剧院上演的最新作品中出演女主角的机会。"}}]},"examples":[{"en":"In many marriages there has been a complete role reversal (= change of roles) with the man staying at home and the woman going out to work.","cn":"许多夫妻彻底交换了角色，男人待在家里而女人出外工作。"},{"en":"It is one of the greatest roles she has played.","cn":"这是她所扮演过的最重要的角色之一。"}]},"roots":{"oxford":{"phon":"ruːts","pos":"","senses":[{"en":"a long novel (1976) by the US writer Alex Haley, for which he received a special Pulitzer Prize. The story, based on Haley's research into his own family's history, is about an African-American family of who were enslaved. A television version (1977) ran for eight nights on ABC and had an audience of about 100 million, the largest ever. It received nine Emmy awards.","cn":"美国作家亚历克斯·黑利的长篇小说（1976），他因此获得普利策特别奖。这个故事基于海利对自己家族历史的研究，讲述了一个被奴役的非裔美国家庭的故事。电视版（1977 年）在美国广播公司 (ABC) 播出八晚，拥有约 1 亿观众，为有史以来最多的一次。它获得了九项艾美奖。"}]},"media":{"img":["media/pic/root_vegetables_comp.jpg","media/thumb/carrot.jpg"],"uk":"media/uk/root__gb_1.mp3","us":"media/us/root__us_1.mp3"}},"rolls-royce":{"oxford":{"phon":"ˌrəʊlz ˈrɔɪs","pos":"noun","senses":[{"en":"a large, comfortable and expensive make of car made by a company in the UK","cn":"劳斯莱斯汽车（英国一种大型豪华轿车）","lab":"informal"},{"en":"something that is thought of as an example of the highest quality of a type of thing","cn":"最优质的品种；最优品","lab":"British English","ex":{"en":"This is the Rolls-Royce of canoes.","cn":"这是独木舟中的极品。"}}]},"media":{"uk":"media/uk/rolls_royce_1_gb_1.mp3","us":"media/us/rolls_royce_1_us_1.mp3"},"examples":[{"en":"This is the Rolls-Royce of canoes.","cn":"这是独木舟中的极品。"},{"en":"the Rolls-Royce of beers","cn":"啤酒中的极品"}]},"road":{"media":{"uk":"media/uk/road__gb_1.mp3","us":"media/us/road__us_1.mp3"},"oxford":{"phon":"rəʊd","pos":"noun","senses":[{"en":"a hard surface built for vehicles to travel on","cn":"路；道路；公路","ex":{"en":"a main/major/minor road","cn":"公路干线；大路；支路"}},{"en":"used in names of roads, especially in towns","cn":"（用于道路名称，尤指城镇的）路","lab":"British English","ex":{"en":"35 York Road","cn":"约克路 35 号"}},{"en":"the way to achieving something","cn":"途径；方法；路子","ex":{"en":"to be on the road to recovery","cn":"正在恢复之中"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路;道路;公路","en":"A road is a long piece of hard ground which is built between two places so that people can drive or ride easily from one place to the other.","ex":{"en":"There was very little traffic on the roads","cn":"这些公路上车辆稀少。"}},{"pos":"N-COUNT 可数名词","cn":"途径;方法;过程","en":"The road to a particular result is the means of achieving it or the process of achieving it.","ex":{"en":"We are bound to see some ups and downs along the road to recovery.","cn":"在经济复苏的过程中，我们一定会经历一些曲折起伏。"}},{"pos":"PHRASE 短语","cn":"出发;动身","en":"If you hit the road, you set out on a journey.","ex":{"en":"I was relieved to get back in the car and hit the road again.","cn":"回到车里重新上路后，我松了一口气。"}},{"pos":"PHRASE 短语","cn":"在旅途中;在路上","en":"If you are on the road, you are going on a long journey or a series of journeys by road.","ex":{"en":"He hoped to get a new truck and go back on the road.","cn":"他希望能有一辆新的卡车，重新上路。"}},{"pos":"PHRASE 短语","cn":"走向…;向…迈进;即将达到","en":"If you say that someone is on the road to something, you mean that they are likely to achieve it.","ex":{"en":"The government took another step on the road to political reform.","cn":"政府在实现政治改革的路上又迈进了一步。"}},{"pos":"","cn":"","en":"the end of the road→see: ;"}]},"examples":[{"en":"We have discussed privatization, but we would prefer not to go down that particular road.","cn":"我们已经讨论了私有化问题，但不想采用这种方法。"},{"en":"It will cost about £500 to get the car back on the road.","cn":"要花大约 500 英镑才能让车子重新上路。"}]},"rock":{"media":{"uk":"media/uk/rock__gb_1.mp3","us":"media/us/rock__us_1.mp3"},"oxford":{"phon":"rɒk","pos":"noun","senses":[{"en":"the hard solid material that forms part of the surface of the earth and some other planets","cn":"岩石","g":"[uncountable, countable]","sc":"hard material","ex":{"en":"They drilled through several layers of rock to reach the oil.","cn":"他们钻透了几层岩石寻找石油。"}},{"en":"a mass of rock standing above the earth’s surface or in the sea","cn":"石山；礁石","g":"[countable]","sc":"hard material","ex":{"en":"the Rock of Gibraltar","cn":"直布罗陀山"}},{"en":"a large single piece of rock","cn":"巨石块；岩块","g":"[countable]","sc":"hard material","ex":{"en":"They clambered over the rocks at the foot of the cliff.","cn":"他们吃力地爬过了绝壁脚下的巨石。"}},{"en":"a small stone","cn":"碎石；石子；小石块","g":"[countable]","lab":"North American English","sc":"stone","ex":{"en":"Protesters pelted the soldiers with rocks.","cn":"抗议者向士兵投掷石块。"}},{"en":"a type of loud popular music, developed in the 1960s, with a strong beat played on electric guitars and drums","cn":"摇滚乐","g":"[uncountable]","sc":"music","ex":{"en":"punk/indie/classic rock","cn":"朋克／独立／经典摇滚乐"}},{"en":"a type of hard sweet made in long sticks, often sold in places where people go on holiday by the sea","cn":"硬棍糖","g":"[uncountable]","lab":"British English","sc":"sweet/candy","ex":{"en":"a stick of Brighton rock","cn":"一支布赖顿硬棍糖"}},{"en":"a precious stone, especially a diamond","cn":"宝石；（尤指）钻石","g":"[countable, usually plural]","lab":"North American English, informal，，","sc":"jewel"},{"en":"a person who is emotionally strong and who you can rely on","cn":"可信赖的人；靠山","g":"[countable, usually singular]","sc":"person","ex":{"en":"He is my rock.","cn":"他是我的主心骨。"}},{"en":"to move gently backwards and forwards or from side to side; to make somebody/something move in this way","cn":"（使）轻轻摇晃，缓缓摆动","g":"[intransitive, transitive]","sc":"move gently","ex":{"en":"The boat rocked from side to side in the waves.","cn":"小船在波浪中摇荡。"},"pos":"verb"},{"en":"to shock somebody/something very much or make them afraid","cn":"惊吓；使震惊；使害怕","g":"[transitive, often passive]","lab":"rather informal","sc":"shock","ex":{"en":"The country was rocked by a series of political scandals.","cn":"一连串的政治丑闻震惊全国。"},"pos":"verb"},{"en":"to shake or to make something shake violently","cn":"（使）剧烈摇摆，猛烈晃动","g":"[intransitive, transitive]","lab":"figurative","sc":"shake","ex":{"en":"The house rocked when the bomb exploded.","cn":"炸弹爆炸时，房子都晃动了。"},"pos":"verb"},{"en":"to dance to rock music","cn":"随摇滚乐跳舞；跳摇滚","g":"[intransitive]","lab":"old-fashioned","sc":"dance","pos":"verb"},{"en":"used to say that something is very good","cn":"很好；棒极了","g":"[intransitive]","lab":"slang","sc":"be good","ex":{"en":"Her new movie rocks!","cn":"她的新电影棒极了！"},"pos":"verb"},{"en":"to wear something or have a style of clothing, hair, etc. that makes you look attractive or confident","cn":"穿…服装，梳…发型（以彰显魅力）","g":"[transitive]","lab":"informal","sc":"fashion","ex":{"en":"How to rock the retro look.","cn":"如何装扮复古风。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"岩石;石头","en":"Rock is the hard substance which the Earth is made of.","ex":{"en":"The hills above the valley are bare rock","cn":"山谷上方的小山全是光秃秃的石头。"}},{"pos":"N-COUNT 可数名词","cn":"巨石;岩石;礁石","en":"A rock is a large piece of rock that sticks up out of the ground or the sea, or that has broken away from a mountain or a cliff.","ex":{"en":"She sat cross-legged on the rock.","cn":"她盘腿坐在那块巨大的岩石上。"}},{"pos":"N-COUNT 可数名词","cn":"石块;小石头;石子","en":"A rock is a piece of rock that is small enough for you to pick up.","ex":{"en":"She bent down, picked up a rock and threw it into the trees.","cn":"她弯腰捡起一块石子，扔进了树丛中。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)来回摆动;(使)左右摇晃","en":"When something rocks or when you rock it, it moves slowly and regularly backwards and forwards or from side to side.","ex":{"en":"His body rocked from side to side with the train","cn":"他的身体随着火车左右摇晃。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）震动;（使）摇晃","en":"If an explosion or an earthquake rocks a building or an area, it causes the building or area to shake. You can also say that the building or area rocks.","ex":{"en":"Three people were injured yesterday when an explosion rocked one of Britain's best known film studios","cn":"昨天，一起爆炸使得英国最著名的电影制片厂之一发生强烈震动，导致3人受伤。"}},{"pos":"VERB 动词","cn":"使震惊;使震动;使不安","en":"If an event or a piece of news rocks a group or society, it shocks them or makes them feel less secure.","ex":{"en":"His death rocked the fashion business.","cn":"他的去世震惊了整个时装界。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"摇滚乐","en":"Rock is loud music with a strong beat that is usually played and sung by a small group of people using instruments such as electric guitars and drums.","ex":{"en":"He once told an interviewer that he didn't even like rock music.","cn":"他曾告诉一位采访者，他甚至都不喜欢摇滚乐。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（常在英国海滨城镇销售的）棒形硬糖","en":"Rock is a sweet that is made in long, hard sticks and is often sold in towns by the sea in Britain.","ex":{"en":"...a stick of rock.","cn":"一条硬棒糖"}},{"pos":"PHRASE 短语","cn":"左右为难;进退维谷","en":"If you are caught between a rock and a hard place, you are in a difficult situation where you have to choose between two equally unpleasant courses of action."},{"pos":"PHRASE 短语","cn":"加冰块的","en":"If you have an alcoholic drink such as whisky on the rocks, you have it with ice cubes in it.","ex":{"en":"...a Scotch on the rocks.","cn":"加冰块的苏格兰威士忌"}},{"pos":"PHRASE 短语","cn":"（婚姻）濒临破裂;（企业等）濒临失败;岌岌可危","en":"If something such as a marriage or a business is on the rocks, it is experiencing very severe difficulties and looks likely to end very soon.","ex":{"en":"She confided to her mother six months ago that her marriage was on the rocks","cn":"6个月前，她向母亲透露自己的婚姻已经岌岌可危。"}},{"pos":"","cn":"","en":"to rock the boat→see: ;"}]},"examples":[{"en":"The ship crashed into the infamous Sker Point rocks and broke into three pieces.","cn":"这艘船撞上了恶名远扬的斯戈尔尖岬暗礁群，断为三截。"},{"en":"The tunnel was blasted out of solid rock.","cn":"这条隧道是在实心岩石中炸出来的。"}]},"rocket":{"oxford":{"phon":"ˈrɒkɪt","pos":"noun","senses":[{"en":"a spacecraft in the shape of a tube that is driven by a stream of gases let out behind it when fuel is burned inside","cn":"火箭","g":"[countable]","ex":{"en":"a space rocket","cn":"太空火箭"}},{"en":"a missile (= a weapon that travels through the air) that carries a bomb and is driven by a stream of burning gases","cn":"火箭武器；火箭（弹）","g":"[countable]","ex":{"en":"a rocket attack","cn":"火箭攻击"}},{"en":"a firework that goes high into the air and then explodes with coloured lights","cn":"焰火；烟花","g":"[countable]"},{"en":"a plant with long green leaves that have a strong taste and are eaten raw in salads","cn":"芝麻菜；芸芥；火箭生菜","g":"[uncountable]","lab":"British English"},{"en":"to increase very quickly and suddenly","cn":"快速增长；猛增","g":"[intransitive]","ex":{"en":"rocketing prices","cn":"飞涨的价格"},"pos":"verb"},{"en":"to move very fast","cn":"疾驰；飞驰","g":"[intransitive]","ex":{"en":"The car rocketed out of a side street.","cn":"汽车从一条小路上嗖的一下开了出来。"},"pos":"verb"},{"en":"to achieve or to make somebody/something achieve a successful position very quickly","cn":"（使）迅速成功，迅速提高地位","g":"[intransitive, transitive]","ex":{"en":"The band rocketed to stardom with their first single.","cn":"这支乐队的第一首单曲使他们一举成名。"},"pos":"verb"},{"en":"to attack a place with rockets","cn":"用火箭弹攻击","g":"[transitive]","pos":"verb"},{"en":"the name of an early steam engine (= vehicle that pulls a train) designed in the 1820s by Robert Stephenson. It was the first engine to be used regularly on the Liverpool and Manchester Railway, and the original version of it is now in the Science Museum, London.","cn":"火箭：罗伯特·史蒂芬森（Robert Stephenson）在1820年代设计的早期蒸汽机（即牵引火车的车辆）的名称。它是利物浦和曼彻斯特铁路上第一个经常使用的发动机，其原始版本现在在伦敦的科学博物馆中。","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"火箭","en":"A rocket is a space vehicle that is shaped like a long tube."},{"pos":"N-COUNT 可数名词","cn":"火箭弹;火箭推进式导弹","en":"A rocket is a missile containing explosive that is powered by gas.","ex":{"en":"There has been a renewed rocket attack on the capital.","cn":"首都遭受了新一轮的火箭袭击。"}},{"pos":"N-COUNT 可数名词","cn":"烟花;焰火","en":"A rocket is a firework that quickly goes high into the air and then explodes."},{"pos":"VERB 动词","cn":"(价格)猛涨，飙升;（社会问题）急剧增多","en":"If things such as prices or social problems rocket, they increase very quickly and suddenly.","ex":{"en":"Fresh food is so scarce that prices have rocketed","cn":"新鲜食物非常匮乏，导致价格猛涨。"}},{"pos":"VERB 动词","cn":"疾驰;飞奔","en":"If something such as a vehicle rockets somewhere, it moves there very quickly.","ex":{"en":"A train rocketed by, shaking the walls of the row houses","cn":"一辆火车疾驰而过，排屋的墙都摇晃起来。"}}]},"media":{"uk":"media/uk/rocket__gb_1.mp3","us":"media/us/rocket__us_1.mp3","img":["media/ldoce/img/rocket.jpg"]},"examples":[{"en":"The band rocketed to stardom with their first single.","cn":"这支乐队的第一首单曲使他们一举成名。"},{"en":"The car rocketed out of a side street.","cn":"汽车从一条小路上嗖地一下开了出来。"}]},"rooted":{"media":{"uk":"media/uk/rooted__gb_1.mp3","us":"media/us/rooted__us_1.mp3"},"oxford":{"phon":"ˈruːtɪd","pos":"adjective","senses":[{"en":"developing from or being strongly influenced by something","cn":"根源在于；由…产生","ex":{"en":"His problems are deeply rooted in his childhood experiences.","cn":"他的问题的祸根在于他童年的经历。"}},{"en":"fixed in one place; not moving or changing","cn":"固定在某地的；稳固的；根深蒂固的","ex":{"en":"She was rooted to her chair.","cn":"她坐在椅子上一动不动。"}},{"en":"extremely tired","cn":"疲惫不堪的；筋疲力尽的","lab":"Australian English, slang，，"},{"en":"too old or broken to use","cn":"老旧无用的；破得不能用的","lab":"Australian English, slang，，"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"起源于…的;根源于…的;由…产生的","en":"If you say that one thing is rooted in another, you mean that it is strongly influenced by it or has developed from it.","ex":{"en":"The crisis is rooted in deep rivalries between the two groups.","cn":"这场危机的根源是这两个群体之间积怨已深的敌对情绪。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（观点、感受）根深蒂固的，难以改变的","en":"If someone has deeply rooted opinions or feelings, they believe or feel something extremely strongly and are unlikely to change.","ex":{"en":"Racism is a deeply rooted prejudice which has existed for thousands of years.","cn":"种族主义是存在了几千年的根深蒂固的偏见。"}},{"pos":"PHRASE 短语","cn":"（因害怕或吃惊）呆住，不能动弹","en":"If you are rooted to the spot, you are unable to move because you are very frightened or shocked.","ex":{"en":"We just stopped there, rooted to the spot.","cn":"我们一下子就停在了那里，呆若木鸡。"}}]},"examples":[{"en":"Racism is still deeply rooted in our society.","cn":"种族主义在我们的社会中仍然根深蒂固。"},{"en":"His problems are deeply rooted in his childhood experiences.","cn":"他的问题的祸根在于他童年的经历。"}]},"rough":{"media":{"uk":"media/uk/rough__gb_1.mp3","us":"media/us/rough__us_1.mp3"},"oxford":{"phon":"rʌf","pos":"adjective","senses":[{"en":"having a surface that is not even or regular","cn":"粗糙的；不平滑的；高低不平的","sc":"not smooth","ex":{"en":"rough ground","cn":"高低不平的地面"}},{"en":"not exact; not including all details","cn":"不确切的；粗略的；大致的","sc":"not exact","ex":{"en":"a rough calculation/estimate of the cost","cn":"对成本的粗略计算／估计"}},{"en":"not gentle or careful; violent","cn":"粗暴的；粗野的；猛烈的","sc":"violent","ex":{"en":"This watch is not designed for rough treatment.","cn":"这块手表不可猛烈震动。"}},{"en":"where there is a lot of violence or crime","cn":"犯罪盛行的；充斥暴力的；危险的","sc":"violent","ex":{"en":"the roughest neighbourhood in the city","cn":"市内最危险的街区"}},{"en":"having large and dangerous waves; wild and with storms","cn":"汹涌的；风浪很大的","sc":"sea/weather","ex":{"en":"It was too rough to sail that night.","cn":"那天夜里风浪太大，无法行船。"}},{"en":"difficult and unpleasant","cn":"艰难的；艰苦的","sc":"difficult","ex":{"en":"He's had a really rough time recently (= he's had a lot of problems).","cn":"他最近真是困难重重。"}},{"en":"not feeling well","cn":"不舒服的；不适的","lab":"British English","sc":"not well","ex":{"en":"You look rough—are you OK?","cn":"你看上去不太舒服，你没事吧？"}},{"en":"simply made and not finished in every detail; plain or basic","cn":"粗糙的；不够精细的；朴实简单的","lab":"British English","sc":"plain/basic","ex":{"en":"rough wooden tables","cn":"粗糙的木桌"}},{"en":"not smooth or pleasant to taste, listen to, etc.","cn":"味道差的；涩的；刺耳的；令人难受的","sc":"not smooth","ex":{"en":"a rough wine/voice","cn":"口感极差的葡萄酒；刺耳的声音"}},{"en":"the part of a golf course where the grass is long, making it more difficult to hit the ball","cn":"（高尔夫球场的）长草区","g":"[singular]","sc":"in golf","ex":{"en":"His second shot ended up in the rough.","cn":"他的第二杆以长草告终。"},"pos":"noun"},{"en":"the first version of a drawing or design that has been done quickly and without much detail","cn":"草稿；草图","g":"[countable]","lab":"specialist","sc":"drawing/design","ex":{"en":"Only the best of the roughs are shown to the editor.","cn":"只有最好的草稿才能拿给编辑看。"},"pos":"noun"},{"en":"a violent person","cn":"暴徒；粗野的人","g":"[countable]","lab":"old-fashioned, informal，，","sc":"violent person","ex":{"en":"a gang of roughs","cn":"一帮暴徒"},"pos":"noun"},{"en":"using force or violence","cn":"粗鲁地；粗野地","ex":{"en":"Do they always play this rough?","cn":"他们比赛总是这么粗野吗？"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(表面)粗糙不平的，不光滑的","en":"If a surface is rough, it is uneven and not smooth.","ex":{"en":"His hands were rough and calloused, from years of karate practice","cn":"由于多年练习空手道，他的双手粗糙不平，布满老茧。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或行为)粗暴的，粗野的，粗鲁的","en":"You say that people or their actions are rough when they use too much force and not enough care or gentleness.","ex":{"en":"Rugby's a rough game at the best of times","cn":"即使是在比赛最不激烈的时候，橄榄球也是一种粗野的运动。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地区、城市、学校等)危险的，充斥暴力的，犯罪率高的","en":"A rough area, city, school, or other place is unpleasant and dangerous because there is a lot of violence or crime there.","ex":{"en":"It was quite a rough part of our town.","cn":"这是我们城里犯罪率很高的地区。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(日子)艰难的，困难的，不愉快的","en":"If you say that someone has had a rough time, you mean that they have had some difficult or unpleasant experiences.","ex":{"en":"All women have a rough time in our society","cn":"在我们的社会中，所有女性的日子都不好过。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"身体不适的;不舒服的","en":"If you feel rough, you feel ill.","ex":{"en":"The virus won't go away and the lad is still feeling a bit rough.","cn":"病毒无法清除，这个小伙子仍然觉得有点不舒服。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(计算、猜测)大概的，粗略的，不精确的","en":"A rough calculation or guess is approximately correct, but not exact.","ex":{"en":"We were only able to make a rough estimate of how much fuel would be required","cn":"我们只能对所需燃料作一个粗略的估计。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(想法、描述)粗略的，简略的，大致的;(图画)简笔的","en":"If you give someone a rough idea, description, or drawing of something, you indicate only the most important features, without much detail.","ex":{"en":"I've got a rough idea of what he looks like","cn":"我已经大致知道他长什么样子了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"做工粗糙的;不精致的;简陋的","en":"You can say that something is rough when it is not neat and well made.","ex":{"en":"...a rough wooden table.","cn":"做工粗糙的木桌子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)恶劣的，狂风暴雨的;(海面)波浪滔天的","en":"If the sea or the weather at sea is rough, the weather is windy or stormy and there are very big waves.","ex":{"en":"A fishing vessel and a cargo ship collided in rough seas.","cn":"一艘捕鱼船和一艘货船在波涛汹涌的海上相撞了。"}},{"pos":"ADV 副词","cn":"风餐露宿地;无家可归地;流浪地","en":"When people sleep or live rough, they sleep out of doors, usually because they have no home.","ex":{"en":"It makes me so sad when I see young people begging or sleeping rough on the streets.","cn":"我看到年轻人沿街乞讨、露宿街头，心里会非常难过。"}},{"pos":"VERB 动词","cn":"过（从前没有过的）艰苦的生活","en":"If you have to rough it, you have to live without the possessions and comforts that you normally have.","ex":{"en":"You won't be roughing it; each room comes equipped with a telephone and a 3-channel radio.","cn":"你不会过得太艰苦;每个房间都配备了一部电话和一台可以接收3个频道的收音机。"}},{"pos":"","cn":"","en":"rough justice→see: ;"},{"pos":"","cn":"","en":"相关词组：rough out rough up"}]},"examples":[{"en":"We can sleep on the beach. I don't mind roughing it for a night or two.","cn":"我们可以睡在海滩上，我不介意吃一两夜的苦。"},{"en":"Trim rough edges with a sharp knife.","cn":"用锋利的刀将参差不齐的边切齐。"}]},"romance":{"media":{"uk":"media/uk/romance__gb_1.mp3","us":"media/us/romance__us_1.mp3"},"oxford":{"phon":"rəʊˈmæns","pos":"noun","senses":[{"en":"an exciting, usually short, relationship between two people who are in love with each other","cn":"（通常指短暂的）浪漫史，爱情关系，风流韵事","g":"[countable]","ex":{"en":"a holiday romance","cn":"假日浪漫史"}},{"en":"love or the feeling of being in love","cn":"恋爱；爱情","g":"[uncountable]","lab":"especially North American English","ex":{"en":"Spring is here and romance is in the air.","cn":"春天来了，到处洋溢着爱情的气息。"}},{"en":"a story about a love affair","cn":"爱情故事","g":"[countable]","ex":{"en":"She's a compulsive reader of romances.","cn":"她热衷于阅读爱情故事。"}},{"en":"a feeling of excitement and adventure, especially connected to a particular place or activity","cn":"传奇色彩；浪漫氛围","g":"[uncountable]","ex":{"en":"the romance of travel","cn":"旅行奇趣"}},{"en":"a story of excitement and adventure, often set in the past","cn":"传奇故事","g":"[countable]","ex":{"en":"medieval romances","cn":"中世纪的传奇故事"}},{"en":"to tell stories that are not true or to describe something in a way that makes it seem more exciting or interesting than it really is","cn":"虚构（故事）；渲染","g":"[intransitive]","pos":"verb"},{"en":"to have or to try to have a romantic relationship with somebody","cn":"和（某人）谈情说爱；追求（某人）","g":"[transitive]","pos":"verb"},{"en":"Romance languages, such as French, Italian and Spanish, are languages that developed from Latin","cn":"罗曼语的（由拉丁语演变而成，如法语、意大利语、西班牙语等）","pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"罗曼史;恋爱;风流韵事","en":"A romance is a relationship between two people who are in love with each other but who are not married to each other.","ex":{"en":"After a whirlwind romance the couple announced their engagement in July.","cn":"在闪电式的恋爱后，两人在7月宣布订婚。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"浪漫;爱意;温馨","en":"Romance refers to the actions and feelings of people who are in love, especially behaviour which is very caring or affectionate.","ex":{"en":"He still finds time for romance by cooking candlelit dinners for his girlfriend","cn":"他仍然会找时间为女友准备烛光晚餐，制造浪漫。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"浪漫情调;传奇色彩","en":"You can refer to the pleasure and excitement of doing something new or exciting as romance .","ex":{"en":"We want to recreate the romance and excitement that used to be part of rail journeys.","cn":"我们想再度营造以前坐火车旅行的浪漫和兴奋。"}},{"pos":"N-COUNT 可数名词","cn":"爱情故事;爱情小说;爱情电影","en":"A romance is a novel or film about a love affair.","ex":{"en":"Her taste in fiction was for chunky historical romances.","cn":"她所喜欢的小说是大部头的历史爱情小说。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（统称）爱情小说","en":"Romance is used to refer to novels about love affairs.","ex":{"en":"Since taking up writing romance in 1967 she has brought out over fifty books.","cn":"自1967年开始写爱情小说起，她已经出了50多本书了。"}},{"pos":"N-VAR 可变名词","cn":"(中世纪的)冒险故事，传奇文学","en":"A medieval romance is a story about adventures such as battles and long journeys.","ex":{"en":"...Arthurian Romances.","cn":"亚瑟王的传奇故事"}},{"pos":"VERB 动词","cn":"和…谈恋爱","en":"When a man romances a woman, he has a love affair with her.","ex":{"en":"He has romanced some of the world's most eligible women.","cn":"他已经和一些非常适合结婚的女人谈过恋爱了。"}},{"pos":"ADJ 形容词","cn":"罗曼语系的（由拉丁语演变而成的语言，如法语、西班牙语、意大利语等）","en":"Romance languages are languages such as French, Spanish, and Italian, which come from Latin."}]},"examples":[{"en":"How can you put the romance back into your marriage?","cn":"怎样才能使你的婚姻再次充满绵绵爱意呢？"},{"en":"They had a whirlwind romance.","cn":"他们之间有过一段短暂的风流韵事。"}]},"ropey":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"差劲的;劣质的;差强人意的","en":"If you say that something is ropey, you mean that its quality is poor or unsatisfactory.","ex":{"en":"Your spelling's a bit ropey","cn":"你的拼写有点难看。"}}]},"media":{"uk":"media/ldoce/hwd/bre/2/ropey0205.mp3","us":"media/ldoce/hwd/ame/9/ld41ropey.mp3"},"examples":[{"en":"I’m feeling a bit ropey this morning.","cn":"今天早上我觉得有些不舒服。"},{"en":"ropey old furniture","cn":"破旧的家具"}]},"rocky":{"media":{"uk":"media/uk/rocky__gb_1.mp3","us":"media/us/rocky__us_1.mp3"},"oxford":{"phon":"ˈrɒki","pos":"adjective","senses":[{"en":"made of rock; full of rocks","cn":"岩石的；多岩石的","ex":{"en":"a rocky coastline","cn":"岩石嶙嶙的海岸线"}},{"en":"difficult and not certain to continue or to be successful","cn":"困难的；难以维持的；不稳定的","ex":{"en":"a rocky marriage","cn":"不稳定的婚姻"}},{"en":"a film character created and played by Sylvester Stallone. He wrote and acted in six successful films about Rocky Balboa, a boxer who succeeds in dealing with many difficulties to finally defeat strong opponents. The first, Rocky (1976), made him famous and won two Oscars. Stallone himself directed Rocky II (1979), Rocky III (1982), Rocky IV (1985), Rocky V (1990) and Rocky Balboa (2006).","cn":"洛基：西尔维斯特·史泰龙创作和扮演的电影角色。他写了六部成功的电影，并饰演了洛基·巴尔波亚（Rocky Balboa），这是一名拳击手，他成功地克服了许多困难，最终击败了强大的对手。第一位是洛基（Rocky，1976年），使他成名并赢得了两次奥斯卡奖。史泰龙亲自执导了《洛基II》（1979），《洛基III》（1982），《洛基IV》（1985），《洛基V》（1990）和洛基巴尔博亚（2006）。","pos":""}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多岩石的;遍布岩石的","en":"A rocky place is covered with rocks or consists of large areas of rock and has nothing growing on it.","ex":{"en":"The paths are often very rocky so strong boots are advisable.","cn":"路上通常石头很多，所以最好穿结实耐磨的靴子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（局势、关系）不稳定的，不稳固的，困难重重的","en":"A rocky situation or relationship is unstable and full of difficulties.","ex":{"en":"They had gone through some rocky times together when Ann was first married","cn":"当安刚结婚时，他们已经一起度过了一些艰难时光。"}}]},"examples":[{"en":"a rocky coastline","cn":"岩石嶙嶙的海岸线"},{"en":"a rocky marriage","cn":"不稳定的婚姻"}]},"row":{"oxford":{"phon":"rəʊ","pos":"noun","senses":[{"en":"a number of people standing or sitting next to each other in a line; a number of objects arranged in a line","cn":"一排；一列；一行","ex":{"en":"There is a row of trees in front of the house.","cn":"房子前面有一排树。"}},{"en":"a line of seats in a cinema, theatre, etc.","cn":"（剧院、电影院等的）一排座位","ex":{"en":"Let's sit in the back row.","cn":"我们坐在最后一排吧。"}},{"en":"a line of numbers or words arranged one after the other across the page in a table","cn":"（图表中的）一行数字（或单词）","ex":{"en":"The top row of Table 2 shows the current values.","cn":"表 2 的最上面一行显示当前值。"}},{"en":"a complete line of stitches in knitting or crochet (= ways of making clothing, etc. out of wool)","cn":"（编织中的）针行；一整行"},{"en":"used in the name of some roads","cn":"（用于某些道路名称）","ex":{"en":"Manor Row","cn":"庄园路"}},{"en":"an act of rowing a boat; the period of time spent doing this","cn":"划船（时间）","g":"[usually singular]","ex":{"en":"We went for a row on the lake.","cn":"我们去湖上划船了。"}},{"en":"to move a boat through water using oars (= long thin straight pieces of wood with flat ends)","cn":"划（船）","g":"[intransitive, transitive]","ex":{"en":"We rowed around the island.","cn":"我们绕着岛划船。"},"pos":"verb"},{"en":"to take somebody somewhere in a boat with oars","cn":"划船送（某人）","g":"[transitive]","ex":{"en":"The fisherman rowed us back to the shore.","cn":"渔夫划船将我们送回到岸上。"},"pos":"verb"},{"en":"a serious argument between people, organizations, etc. about something","cn":"严重分歧；纠纷","g":"[countable]","ex":{"en":"A row has broken out over education.","cn":"在教育问题上出现了严重分歧。"}},{"en":"a noisy argument between two or more people","cn":"吵架；争吵","g":"[countable]","ex":{"en":"She left him after a blazing row.","cn":"大吵一场之后，她离他而去。"}},{"en":"a loud unpleasant noise","cn":"大的噪音","g":"[singular]","ex":{"en":"Who's making that row?","cn":"谁那么吵？"}},{"en":"to have a noisy argument","cn":"吵架；大声争辩","ex":{"en":"Mike and Sue are always rowing.","cn":"迈克和休总是吵架。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一排;一行;一列","en":"A row of things or people is a number of them arranged in a line.","ex":{"en":"...a row of pretty little cottages","cn":"一排漂亮的小村舍"}},{"pos":"N-COUNT 可数名词","cn":"(电影院或飞机里的)一排座位","en":"In a theatre or cinema, or on a plane, each line of seats is called a row .","ex":{"en":"She was sitting in the front row.","cn":"她坐在前排。"}},{"pos":"N-IN-NAMES 名称名词","cn":"(用于街道名称)…街，…路","en":"Row is sometimes used in the names of streets.","ex":{"en":"...the house at 236 Larch Row.","cn":"拉奇街236号的房子"}},{"pos":"PHRASE 短语","cn":"连续地;接连不断地;不间断地","en":"If something happens several times in a row, it happens that number of times without a break. If something happens several days in a row, it happens on each of those days.","ex":{"en":"They have won five championships in a row","cn":"他们已经5次蝉联冠军。"}},{"pos":"","cn":"","en":"a hard row to hoe→see: ;"},{"pos":"VERB 动词","cn":"划船;划船运送","en":"When you row, you sit in a boat and make it move through the water by using oars. If you row someone somewhere, you take them there in a boat, using oars.","ex":{"en":"He rowed as quickly as he could to the shore","cn":"他尽快地把船划到岸边。"}},{"pos":"","cn":"","en":"相关词组：row back"},{"pos":"N-COUNT 可数名词","cn":"严重分歧;纠纷","en":"A row is a serious disagreement between people or organizations.","ex":{"en":"This is likely to provoke a further row about the bank's role in the affair","cn":"这有可能会加深关于银行在此事中的作用的分歧。"}},{"pos":"N-COUNT 可数名词","cn":"争吵;争执;争论","en":"If two people have a row, they have a noisy argument.","ex":{"en":"We never seem to stay together for very long before we have a dreadful row","cn":"我们总是在一起呆不了多久就会大吵一架。"}},{"pos":"V-RECIP 相互动词","cn":"争吵;争执;争论","en":"If two people row or if one person rows with another, they have a noisy argument.","ex":{"en":"They rowed all the time","cn":"他们总是争吵不休。"}},{"pos":"N-SING 单数名词","cn":"叫嚷;吵闹;喧嚣","en":"If you say that someone is making a row, you mean that they are making a loud, unpleasant noise.","ex":{"en":"'Whatever is that row?' she demanded. 'Pop festival,' he answered.","cn":"“那闹哄哄的究竟是在做什么？”她问道。“是流行音乐节，”他回答说。"}}]},"media":{"uk":"media/uk/row__gb_1.mp3","us":"media/us/row__us_1.mp3","img":["media/ldoce/img/row_seats.jpg"]},"examples":[{"en":"Inflation has fallen for the third month in a row.","cn":"通货膨胀率连续第三个月在下降。"},{"en":"She had rowed with her parents about her boyfriend.","cn":"她和父母因为她的男朋友吵过架。"}]},"royal":{"media":{"uk":"media/uk/royal__gb_1.mp3","us":"media/us/royal__us_1.mp3"},"oxford":{"phon":"ˈrɔɪəl","pos":"adjective","senses":[{"en":"connected with or belonging to the king or queen of a country","cn":"国王的；女王的；皇家的；王室的","ex":{"en":"the royal family","cn":"王室"}},{"en":"used in the names of organizations that serve or are supported by a king or queen","cn":"（用于服务于国王或女王或受其赞助的组织名称）","ex":{"en":"the Royal Navy","cn":"英国皇家海军"}},{"en":"impressive; suitable for a king or queen","cn":"庄严的；盛大的；高贵的；适合国王（或女王）的","ex":{"en":"We were given a royal welcome.","cn":"我们受到了盛大的欢迎。"}},{"en":"a member of a royal family","cn":"王室成员","ex":{"en":"The Queen will be joined by other royals at this evening's performance.","cn":"女王将与其他王室成员一起参加今晚的表演。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"国王的;女王的;王室的;皇室的","en":"Royal is used to indicate that something is connected with a king, queen, or emperor, or their family. A royal person is a king, queen, or emperor, or a member of their family.","ex":{"en":"...an invitation to a royal garden party.","cn":"参加皇家游园会的邀请"}},{"pos":"ADJ 形容词","cn":"（用于机构或组织名称）皇家的","en":"Royal is used in the names of institutions or organizations that are officially appointed or supported by a member of a royal family.","ex":{"en":"...the Royal Academy of Music.","cn":"皇家音乐学院"}},{"pos":"N-COUNT 可数名词","cn":"王室成员;皇族","en":"Members of the royal family are sometimes referred to as royals .","ex":{"en":"The royals have always been patrons of charities pulling in large donations.","cn":"王室成员一向热心慈善事业，捐资数目巨大。"}}]},"examples":[{"en":"We were given a royal welcome.","cn":"我们受到了盛大的欢迎。"},{"en":"the Royal Society for the Protection of Birds","cn":"皇家鸟类保护协会"}]},"roller":{"media":{"img":["media/pic/decorating_diy_comp.jpg","media/thumb/roller.jpg"],"uk":"media/uk/roller__gb_1.mp3","us":"media/us/roller__us_1.mp3"},"oxford":{"phon":"ˈrəʊlə(r)","pos":"noun","senses":[{"en":"a piece of wood, metal or plastic, like a tube in shape, that rolls over and over, used as a tool or as part of a machine, for example to make something flat or to move something","cn":"滚筒；滚轴","ex":{"en":"Flatten the surface of the grass with a roller.","cn":"用碾轧机把草轧平。"}},{"en":"a long, powerful wave in the sea","cn":"卷浪；巨浪","ex":{"en":"Huge Atlantic rollers crashed onto the rocks.","cn":"大西洋的巨浪冲击着岩石。"}},{"en":"a small plastic tube that hair is rolled around to make it curly","cn":"塑料发卷","ex":{"en":"heated rollers","cn":"经过加热的发卷"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滚筒;滚轴;碾子","en":"A roller is a cylinder that turns round in a machine or device."},{"pos":"N-COUNT 可数名词","cn":"卷发筒;发卷","en":"Rollers are hollow tubes that women roll their hair round in order to make it curly."}]},"examples":[{"en":"We'll need to move the piano on rollers.","cn":"我们需要用滚子来移动钢琴。"},{"en":"Huge Atlantic rollers crashed onto the rocks.","cn":"大西洋的巨浪冲击着岩石。"}]},"roving":{"media":{"uk":"media/uk/roving__gb_1.mp3","us":"media/us/roving__us_1.mp3"},"oxford":{"phon":"ˈrəʊvɪŋ","pos":"adjective","senses":[{"en":"travelling from one place to another and not staying anywhere permanently","cn":"流动的；漂泊的；漫游的；巡回的","ex":{"en":"a roving reporter for ABC news","cn":"美国广播公司的流动新闻记者"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（人）流动的，漂泊的,不固定的","en":"You use roving to describe a person who travels around, rather than staying in a fixed place.","ex":{"en":"...a roving reporter","cn":"流动记者"}},{"pos":"PHRASE 短语","cn":"(男人)好色，眼神不安分","en":"If you say that a man has a roving eye, you are criticizing him for continually paying attention to different women."}]},"examples":[{"en":"Patrick's roving lifestyle takes him between London and Los Angeles.","cn":"帕特里克漂泊不定的生活方式使他在伦敦和洛杉矶之间奔波。"},{"en":"a roving reporter for ABC news","cn":"美国广播公司的流动新闻记者"}]},"route":{"media":{"uk":"media/uk/route__gb_1.mp3","us":"media/us/route__us_1.mp3"},"oxford":{"phon":"ruːt","pos":"noun","senses":[{"en":"a way that you follow to get from one place to another","cn":"路线；路途","ex":{"en":"Which is the best route to take?","cn":"哪一条是最佳路线？"}},{"en":"a fixed way along which a bus, train, etc. regularly travels or goods are regularly sent","cn":"（公共汽车和列车等的）常规路线，固定线路","ex":{"en":"The house is not on a bus route.","cn":"这房子不在公交线上。"}},{"en":"a particular way of achieving something","cn":"途径；渠道","ex":{"en":"to go down/take/follow a particular route","cn":"走特定路线"}},{"en":"used before the number of a main road in the US","cn":"（用于美国干线公路号码前）","ex":{"en":"Route 66","cn":"66 号公路"}},{"en":"to send somebody/something by a particular route","cn":"按某路线发送","ex":{"en":"Satellites route data all over the globe.","cn":"卫星向全球各地传递信息。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"道路;路线;路途","en":"A route is a way from one place to another.","ex":{"en":"...the most direct route to the town centre","cn":"到市中心最直接的路线"}},{"pos":"N-COUNT 可数名词","cn":"行车路线;航线","en":"A bus, air, or shipping route is the way between two places along which buses, planes, or ships travel regularly.","ex":{"en":"...the main shipping routes to Japan.","cn":"去往日本的主要航运线路"}},{"pos":"N-IN-NAMES 名称名词","cn":"(用于美国干线公路号码前)","en":"In the United States, Route is used in front of a number in the names of main roads between major cities.","ex":{"en":"...the Broadway-Webster exit on Route 580.","cn":"580号公路的百老汇－韦伯斯特出口"}},{"pos":"N-COUNT 可数名词","cn":"(作为工作的)走访，拜访","en":"Your route is the series of visits you make to different people or places, as part of your job.","ex":{"en":"He began cracking open big blue tins of butter cookies and feeding the dogs on his route","cn":"他打开装黄油饼干的蓝色大罐子，开始沿路给狗喂食。"}},{"pos":"N-COUNT 可数名词","cn":"途径;方法","en":"You can refer to a way of achieving something as a route .","ex":{"en":"Researchers are trying to get at the same information through an indirect route","cn":"研究人员正试图通过间接的途径获得相同的信息。"}},{"pos":"VERB 动词","cn":"按特定路线发送(车辆、货物或乘客)","en":"If vehicles, goods, or passengers are routed in a particular direction, they are made to travel in that direction.","ex":{"en":"Double-stack trains are taking a lot of freight that used to be routed via trucks","cn":"以往由卡车运送的很多货物现在都改用双层列车运送了。"}},{"pos":"VERB 动词","cn":"以…线路发送(电话或其他电子信号)","en":"If telephone calls or other electronic signals are routed in a particular way, the signals are sent through a particular series of connections.","ex":{"en":"...plans to route every emergency call in Britain through just three telephone exchanges.","cn":"只通过3次电话转接来传送英国境内所有紧急呼叫的计划"}},{"pos":"PHRASE 短语","cn":"在途中，沿途(在不规范英语中有时拼作on route)","en":"En route to a place means on the way to that place. En route is sometimes spelled on toute in non-standard English.","ex":{"en":"They have arrived in London en route to the United States","cn":"他们已经到达伦敦，正在前往美国的途中。"}},{"pos":"PHRASE 短语","cn":"（新闻用语）作为（较长进程）的一部分，在…之前","en":"Journalists sometimes use en route when they are mentioning an event that happened as part of a longer process or before another event.","ex":{"en":"The German set three tournament records and equalled two others en route to grabbing golf's richest prize.","cn":"那个德国人在获得高尔夫球赛最高奖金的同时刷新了3项锦标赛纪录，平了其他两项纪录。"}},{"pos":"PHRASE 短语","cn":"把事情进行到底;贯彻始终","en":"If you go the route, you do something fully or continue with a task until you have completely finished.","ex":{"en":"They have gone the route, in many cases, of just big — big bowls, big statues, big masks, big everything.","cn":"在很多情况下，他们从头到尾都只做大的东西——大碗，大雕像，大面具，所有东西都是大的。"}}]},"examples":[{"en":"the quickest route from Florence to Rome","cn":"从佛罗伦萨到罗马的最快捷的路线"},{"en":"Satellites route data all over the globe.","cn":"卫星向全球各地传递信息。"}]},"rounding":{"oxford":{"phon":"ˈraʊndɪŋ","pos":"noun","senses":[{"en":"the fact of producing a speech sound with the lips in the shape of a circle","cn":"发圆唇音；圆唇"}]},"media":{"uk":"media/uk/rounding__gb_1.mp3","us":"media/us/rounding__us_1.mp3"}},"roof":{"media":{"uk":"media/uk/roof__gb_1.mp3","us":"media/us/roof__us_1.mp3","img":["media/ldoce/img/roof.jpg"]},"oxford":{"phon":"ruːf","pos":"noun","senses":[{"en":"the structure that covers or forms the top of a building or vehicle","cn":"顶部；屋顶；车顶","ex":{"en":"a flat/sloping/pitched roof","cn":"平顶；斜顶；坡顶"}},{"en":"having the type of roof mentioned","cn":"有…顶的","ex":{"en":"flat-roofed buildings","cn":"平顶的大楼"}},{"en":"the top of an underground space such as a tunnel or cave","cn":"洞顶；隧道顶","ex":{"en":"The roof of the tunnel was starting to collapse.","cn":"隧道的顶部开始倒塌。"}},{"en":"the top of the inside of your mouth","cn":"口腔顶部；腭部"},{"en":"to cover something with a roof; to put a roof on a building","cn":"给…盖顶；盖上屋顶","ex":{"en":"The shopping centre is not roofed over.","cn":"购物中心是露天的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"房顶;屋顶","en":"The roof of a building is the covering on top of it that protects the people and things inside from the weather.","ex":{"en":"...a small stone cottage with a red slate roof","cn":"有着红色石板房顶的小石屋"}},{"pos":"N-COUNT 可数名词","cn":"顶篷;车顶;车篷","en":"The roof of a car or other vehicle is the top part of it, which protects passengers or goods from the weather.","ex":{"en":"The car rolled onto its roof, trapping him.","cn":"车翻了，把他困在了里面。"}},{"pos":"N-COUNT 可数名词","cn":"口腔顶部;上腭","en":"The roof of your mouth is the highest part of the inside of your mouth.","ex":{"en":"She clicked her tongue against the roof of her mouth.","cn":"她用舌头顶着上腭发出啧啧声。"}},{"pos":"N-COUNT 可数名词","cn":"(洞穴、矿井等的)顶部","en":"The roof of an underground space such as a cave or mine is the highest part of it.","ex":{"en":"The cave roof collapsed.","cn":"洞顶坍塌了。"}},{"pos":"PHRASE 短语","cn":"（价格、通货膨胀率等）猛增，飞涨","en":"If the level of something such as the price of a product or the rate of inflation goes through the roof, it suddenly increases very rapidly indeed.","ex":{"en":"Prices for Korean art have gone through the roof.","cn":"韩国艺术品的价格飞涨。"}},{"pos":"PHRASE 短语","cn":"怒气冲天;大发雷霆;暴跳如雷","en":"If you hit the roof or go through the roof, you become very angry indeed, and usually show your anger by shouting at someone.","ex":{"en":"Sergeant Long will hit the roof when I tell him you've gone off.","cn":"如果我告诉朗中士你已经走了，他会大发雷霆的。"}},{"pos":"PHRASE 短语","cn":"住处;家","en":"If you have a roof over your head, you have somewhere to live.","ex":{"en":"I am just thankful that we have a roof over our heads.","cn":"我们有地方住我就很感激了。"}},{"pos":"PHRASE 短语","cn":"（在屋内）喧闹，喧嚣，大闹翻天","en":"If a group of people inside a building raise the roof, they make a very loud noise, for example by singing or shouting.","ex":{"en":"He raised the roof at the conference when he sang his own version of the socialist anthem, The Red Flag.","cn":"他演唱自己改编的社会主义赞歌《红旗颂》时，声音穿透了会场的屋顶。"}},{"pos":"PHRASE 短语","cn":"同在一个屋檐下;在同一栋大楼里","en":"If a number of things or people are under one roof or under the same roof, they are in the same building.","ex":{"en":"The firms intend to open either together under one roof or alongside each other in shopping malls","cn":"这些公司想一起开在同一栋大楼里，或者彼此紧挨着开在大型购物中心里。"}},{"pos":"PHRASE 短语","cn":"在…的家里","en":"If something happens under your roof, it happens in your home.","ex":{"en":"Lionel has forbidden her ever to mention that name again under his roof.","cn":"莱昂内尔已经禁止她在他家里再提到这个名字。"}}]},"examples":[{"en":"I don't think I can live under the same roof as you any longer.","cn":"我觉得我再也不能和你生活在同一个屋檐下了。"},{"en":"There are various stores and restaurants all under one roof.","cn":"在同一栋大楼里有各种商店和餐馆。"}]},"robber":{"media":{"uk":"media/uk/robber__gb_1.mp3","us":"media/us/robber__us_1.mp3"},"oxford":{"phon":"ˈrɒbə(r)","pos":"noun","senses":[{"en":"a person who steals from a person or place, especially using violence or threats","cn":"强盗；盗贼；抢劫犯","ex":{"en":"a bank robber","cn":"银行抢劫犯"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"强盗;盗贼;抢劫犯","en":"A robber is someone who steals money or property from a bank, a shop, or a vehicle, often by using force or threats. →see usage note at:","ex":{"en":"Armed robbers broke into a jeweller's through a hole in the wall.","cn":"持械抢劫者通过墙上的一个洞闯进了一家珠宝店。"}}]},"examples":[{"en":"a bank robber","cn":"银行抢劫犯"},{"en":"Armed robbers broke into the shop and demanded money from the till.","cn":"持枪劫匪闯进商店﹐索要现金出纳机里的钱。"}]},"rowed":{"oxford":{"phon":"rəʊ","pos":"noun","senses":[{"en":"a number of people standing or sitting next to each other in a line; a number of objects arranged in a line","cn":"一排；一列；一行"},{"en":"a line of seats in a cinema/movie theater, etc. （","cn":"剧院、电影院等的）一排座位"}]}},"rope":{"media":{"img":["media/ldoce/img/rope.jpg","media/pic/rope_comp.jpg"],"uk":"media/uk/rope__gb_1.mp3","us":"media/us/rope__us_1.mp3"},"oxford":{"phon":"rəʊp","pos":"noun","senses":[{"en":"very strong thick string made by twisting thinner strings, wires, etc. together","cn":"粗绳；线缆；绳索","g":"[countable, uncountable]","ex":{"en":"The rope broke and she fell 50 metres onto the rocks.","cn":"绳索断了，她从 50 米的高空摔到了岩石上。"}},{"en":"the fence made of rope that is around the edge of the area where a boxing or wrestling match takes place","cn":"（拳击或摔跤场四周的）围绳，圈绳","g":"[plural]"},{"en":"a number of similar things attached together by a string or thread","cn":"串在一起的相似的东西","g":"[countable]","ex":{"en":"a rope of pearls","cn":"一串珍珠"}},{"en":"to tie one person or thing to another with a rope","cn":"用绳子捆（或绑、系）","ex":{"en":"The thieves had roped the guard's feet together.","cn":"窃贼把门卫的双脚捆在了一起。"},"pos":"verb"},{"en":"to tie something with a rope so that it is held tightly and safely","cn":"用绳子系牢；捆紧","ex":{"en":"I closed and roped the trunk.","cn":"我把箱子盖上，用绳子捆结实。"},"pos":"verb"},{"en":"to catch an animal by throwing a circle of rope around it","cn":"用套索抓捕（动物）；套","lab":"especially North American English","pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"粗绳;绳索;缆绳","en":"A rope is a thick cord or wire that is made by twisting together several thinner cords or wires. Ropes are used for jobs such as pulling cars, tying up boats, or tying things together.","ex":{"en":"He tied the rope around his waist.","cn":"他把绳索系在自己的腰上。"}},{"pos":"VERB 动词","cn":"(用绳索)捆，绑，拴","en":"If you rope one thing to another, you tie the two things together with a rope.","ex":{"en":"I roped myself to the chimney.","cn":"我用绳子把自己系在烟囱上。"}},{"pos":"N-PLURAL 复数名词","cn":"(拳击或摔跤场地的)围绳，圈绳","en":"The ropes refers to the fence made of rope that surrounds a boxing ring or a wrestling ring.","ex":{"en":"He was knocked through the ropes by Tafer.","cn":"他被塔费尔一拳打得从围绳间摔出了场外。"}},{"pos":"PHRASE 短语","cn":"任由…自作自受;任…作茧自缚;任…出丑","en":"If you give someone enough rope to hang themselves, you give them the freedom to do a job in their own way because you hope that their attempts will fail and that they will look foolish.","ex":{"en":"The King has merely given the politicians enough rope to hang themselves","cn":"国王只不过是给了这些政客自缚的绳子。"}},{"pos":"PHRASE 短语","cn":"熟悉门道;学习窍门","en":"If you are learning the ropes, you are learning how a particular task or job is done."},{"pos":"PHRASE 短语","cn":"懂行;在行;熟悉技巧","en":"If you know the ropes, you know how a particular job or task should be done.","ex":{"en":"The moment she got to know the ropes, there was no stopping her.","cn":"一旦她懂行了，就什么也难不住她了。"}},{"pos":"PHRASE 短语","cn":"轻松赚来的钱","en":"If you describe a payment as money for old rope, you are emphasizing that it is earned very easily, for very little effort."},{"pos":"PHRASE 短语","cn":"处境艰难;即将放弃;濒临失败;走投无路","en":"If you say that someone is on the ropes, you mean that they are very near to giving up or being defeated.","ex":{"en":"The army claims the rebels are on the ropes.","cn":"军队声称叛军支撑不了多久了。"}},{"pos":"PHRASE 短语","cn":"教…如何做;教…方法;教…诀窍","en":"If you show someone the ropes, you show them how to do a particular job or task."},{"pos":"","cn":"","en":"相关词组：rope in rope off"}]},"examples":[{"en":"The question was vague, giving the interviewee enough rope to hang herself.","cn":"这个问题模棱两可，让参加面试的人胡乱发挥而自毙吧。"},{"en":"The rope broke and she fell 50 metres onto the rocks.","cn":"绳索断了，她从 50 米的高空摔到了岩石上。"}]},"romans":{"oxford":{"phon":"ˈrəʊmən","pos":"adjective","senses":[{"en":"connected with ancient Rome or the Roman Empire","cn":"古罗马的；古罗马帝国的"},{"en":"connected with the modern city of Rome","cn":"罗马的；罗马城的"}]},"media":{"uk":"media/uk/roman__gb_1.mp3","us":"media/us/roman__us_1.mp3"}},"rob":{"media":{"uk":"media/uk/rob__gb_1.mp3","us":"media/us/rob__us_1.mp3"},"oxford":{"phon":"rɒb","pos":"verb","senses":[{"en":"to steal money or property from a person or place","cn":"抢劫；掠夺；盗取","lab":"British English","ex":{"en":"to rob a bank","cn":"抢劫银行"}},{"en":"a first name for boys, short for Robert","cn":"罗布（男子名，Robert 缩写）","pos":""}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"抢劫;抢夺;打劫","en":"If someone is robbed, they have money or property stolen from them.","ex":{"en":"Mrs Yacoub was robbed of her £3,000 designer watch at her West London home","cn":"雅各布夫人那块价值3,000英镑的名牌手表在西伦敦的家中被人抢走了。"}},{"pos":"VERB 动词","cn":"夺走;剥夺","en":"If someone is robbed of something that they deserve, have, or need, it is taken away from them.","ex":{"en":"When Miles Davis died, jazz was robbed of its most distinctive voice","cn":"随着迈尔斯·戴维斯的去世，爵士乐界失去了其最与众不同的声音。"}}]},"examples":[{"en":"A last-minute goal robbed the team of victory.","cn":"最后一分钟的进球夺去了这支球队胜利的机会。"},{"en":"The tomb had been robbed of its treasures.","cn":"这座坟墓里的财宝早已被盗。"}]},"rosy":{"media":{"uk":"media/uk/rosy__gb_1.mp3","us":"media/us/rosy__us_1.mp3"},"oxford":{"phon":"ˈrəʊzi","pos":"adjective","senses":[{"en":"pink and pleasant in appearance","cn":"粉红色的；红润的","ex":{"en":"She had rosy cheeks.","cn":"她脸颊红润。"}},{"en":"likely to be good or successful","cn":"美好的；乐观的","ex":{"en":"The future is looking very rosy for our company.","cn":"我们公司的前景一片光明。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(脸颊)红润的，红扑扑的","en":"If you say that someone has a rosy face, you mean that they have pink cheeks and look very healthy.","ex":{"en":"Bethan's round, rosy face seemed hardly to have aged at all","cn":"贝唐红扑扑的圆脸看起来似乎一点也没有变老。"}},{"pos":"ADJ 形容词","cn":"红粉色的;玫瑰色的","en":"Something that is rosy is reddish-pink in colour.","ex":{"en":"...the rosy brick buildings.","cn":"红粉色砖砌大楼"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满希望的;前景美好的;有望成功的","en":"If you say that a situation looks rosy or that the picture looks rosy, you mean that the situation seems likely to be good or successful.","ex":{"en":"Little over a year ago, things looked very rosy for the Social Democrats","cn":"一年多以前，社会民主党人的形势看起来一片大好。"}}]},"examples":[{"en":"She painted a rosy picture of their life together in Italy (= made it appear to be very good and perhaps better than it really was).","cn":"她把他们在意大利的共同生活描绘得非常美好。"},{"en":"The future is looking very rosy for our company.","cn":"我们公司的前景一片光明。"}]},"rode":{"collins":{"senses":[{"pos":"","cn":"","en":"Rode is the past tense of ride."}]},"media":{"uk":"media/uk/rode__gb_1.mp3","us":"media/us/rode__us_1.mp3"}},"romeo":{"oxford":{"phon":"ˈrəʊmiəʊ","pos":"noun","senses":[{"en":"a man who has a lot of sexual relationships","cn":"年轻的男情人；风流放荡的男子"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"热恋中的男子;风流的男人;好色之徒","en":"You can describe a man as a Romeo if you want to indicate that he is very much in love with a woman, or that he frequently has sexual relationships with different women.","ex":{"en":"Asked if any other children were planned, the 54-year-old Romeo said: 'Maybe, I dunno.'","cn":"当问到有没有计划再生孩子时，这位热恋中的54岁男子说：“也许吧，我不知道。”"}}]},"media":{"uk":"media/uk/romeo__gb_1.mp3","us":"media/us/romeo__us_1.mp3"}},"rolling":{"media":{"uk":"media/uk/rolling__gb_1.mp3","us":"media/us/rolling__us_1.mp3"},"oxford":{"phon":"ˈrəʊlɪŋ","pos":"adjective","senses":[{"en":"having gentle slopes","cn":"起伏的"},{"en":"done in regular stages or at regular intervals over a period of time","cn":"规则的；周而复始的","ex":{"en":"a rolling programme of reform","cn":"逐步推进的改革计划"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（山丘）起伏的，绵延的","en":"Rolling hills are small hills with gentle slopes that extend a long way into the distance.","ex":{"en":"...the rolling countryside of south western France.","cn":"法国西南部绵延起伏的乡村"}},{"pos":"ADJ 形容词","cn":"(走路)左右摇晃的，摇摆的","en":"If someone has a rolling walk, they move from side to side as they walk.","ex":{"en":"Burns is a big lad with a rolling gait.","cn":"伯恩斯是一个走起路来一摇一晃的高大小伙子。"}},{"pos":"PHRASE 短语","cn":"非常有钱;十分富有","en":"If you say that someone is rolling in it or is rolling in money, you mean that they are very rich."}]},"examples":[{"en":"a rolling programme of reform","cn":"逐步推进的改革计划"},{"en":"We recommend a rolling programme of machine upgrading.","cn":"我们推荐一个逐步实施的机器升级方案。"}]},"rotate":{"oxford":{"phon":"rəʊˈteɪt","pos":"verb","senses":[{"en":"to move or turn around a central fixed point; to make something do this","cn":"（使）旋转，转动","g":"[intransitive, transitive]","ex":{"en":"Stay well away from the helicopter when its blades start to rotate.","cn":"直升机的螺旋桨开始转动时，尽量离远点儿。"}},{"en":"if a job rotates, or if people rotate a job, they regularly change the job or regularly change who does the job","cn":"（工作）由…轮值；（人员）轮换，轮值","g":"[intransitive, transitive]","ex":{"en":"The EU presidency rotates among the members.","cn":"欧盟主席一职由其成员国轮流担任。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)旋转;(使)转动","en":"When something rotates or when you rotate it, it turns with a circular movement.","ex":{"en":"The Earth rotates round the sun","cn":"地球围绕太阳转。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）轮流;（使）轮换","en":"If people or things rotate, or if someone rotates them, they take it in turns to do a particular job or serve a particular purpose.","ex":{"en":"The members of the club can rotate and one person can do all the preparation for the evening","cn":"俱乐部的成员可以轮流工作，而且一个人就能做好晚上的所有准备工作。"}}]},"media":{"uk":"media/uk/rotate__gb_1.mp3","us":"media/us/rotate__us_1.mp3"},"examples":[{"en":"We rotate the night shift so no one has to do it all the time.","cn":"我们轮流值夜班，这样就不会有人总是夜班了。"},{"en":"Stay well away from the helicopter when its blades start to rotate.","cn":"直升机的螺旋桨开始转动时，尽量离远点儿。"}]},"round":{"media":{"uk":"media/uk/round__gb_1.mp3","us":"media/us/round__us_1.mp3"},"oxford":{"phon":"raʊnd","pos":"adjective","senses":[{"en":"having a shape like a circle or a ball","cn":"圆形的；环形的；球形的","ex":{"en":"a round plate","cn":"圆盘子"}},{"en":"having a curved shape","cn":"弧形的；圆弧的","ex":{"en":"the round green hills of Donegal","cn":"多尼戈尔那些圆圆的绿山冈"}},{"en":"a round figure or amount is one that is given as a whole number, usually one ending in 0","cn":"整数的；尾数是 0 的","g":"[only before noun]","ex":{"en":"Make it a round figure—say forty dollars.","cn":"凑个整数，就四十块钱吧。"}},{"en":"moving in a circle","cn":"旋转；环绕；兜圈子","lab":"figurative","ex":{"en":"Everybody joins hands and dances round.","cn":"大家手拉着手，围成一圈跳舞。"},"pos":"adverb"},{"en":"measuring or marking the edge or outside of something","cn":"周长；周围；绕一整圈","ex":{"en":"a young tree measuring only 18 inches round","cn":"周长只有 18 英寸的小树"},"pos":"adverb"},{"en":"on all sides of somebody/something","cn":"在周围；围绕","ex":{"en":"A large crowd had gathered round to watch.","cn":"一大群人聚在周围观看。"},"pos":"adverb"},{"en":"at various places in an area","cn":"到处；四处","ex":{"en":"People stood round waiting for something to happen.","cn":"人们在各处站着，等待着发生什么事情。"},"pos":"adverb"},{"en":"in a circle or curve to face another way or the opposite way","cn":"调转方向；转过来","ex":{"en":"He turned the car round and drove back again.","cn":"他调转车头，又开了回来。"},"pos":"adverb"},{"en":"to the other side of something","cn":"绕弯；迂回；向另一侧","ex":{"en":"We walked round to the back of the house.","cn":"我们绕到房子的后面。"},"pos":"adverb"},{"en":"from one place, person, etc. to another","cn":"依次；挨个","ex":{"en":"They've moved all the furniture round.","cn":"他们把所有的家具搬动了一遍。"},"pos":"adverb"},{"en":"to or at a particular place, especially where somebody lives","cn":"到某地，在某地（尤指居住地）","lab":"informal","ex":{"en":"I'll be round in an hour.","cn":"我过一个小时就到。"},"pos":"adverb"},{"en":"in a circle","cn":"环绕；围绕","ex":{"en":"the first woman to sail round the world","cn":"第一位环球航行的女性"},"pos":"preposition"},{"en":"on, to or from the other side of something","cn":"绕过；在另一侧","lab":"figurative","ex":{"en":"Our house is round the next bend.","cn":"前面一拐弯就是我们家。"},"pos":"preposition"},{"en":"on all sides of somebody/something; surrounding somebody/something","cn":"在…周围；包围","ex":{"en":"She put her arms round him.","cn":"她张开双臂搂住他。"},"pos":"preposition"},{"en":"in or to many parts of something","cn":"在…各处；到…各部分","ex":{"en":"She looked all round the room.","cn":"她将房间四下打量了一下。"},"pos":"preposition"},{"en":"to fit in with particular people, ideas, etc.","cn":"适应；围绕（人、思想等）","lab":"British English","ex":{"en":"He has to organize his life round the kids.","cn":"他不得不以孩子们为中心来安排自己的生活。"},"pos":"preposition"},{"en":"a stage in a competition or sports event","cn":"比赛阶段；轮次；局；场","sc":"in competitions","ex":{"en":"the qualifying rounds of the National Championships","cn":"全国锦标赛的资格赛"},"pos":"noun"},{"en":"a stage in a boxing or wrestling match","cn":"（拳击或摔跤比赛的）回合","sc":"in competitions","ex":{"en":"The fight only lasted five rounds.","cn":"比赛只持续了五个回合。"},"pos":"noun"},{"en":"a complete game of golf; a complete way around the course in some other sports, such as showjumping","cn":"（高尔夫球、马术场地障碍赛等的）一轮比赛，一局，一场","sc":"in competitions","ex":{"en":"We played a round of golf.","cn":"我们打了一场高尔夫球。"},"pos":"noun"},{"en":"a set of events which form part of a longer process","cn":"阶段；轮次","sc":"stage in process","ex":{"en":"the next round of peace talks","cn":"下一轮和谈"},"pos":"noun"},{"en":"a regular series of activities","cn":"一系列常规活动；惯常的活动","sc":"regular activities/route","ex":{"en":"the daily round of school life","cn":"学校的日常生活"},"pos":"noun"},{"en":"a regular route that somebody takes when delivering or collecting something; a regular series of visits that somebody makes","cn":"（收发信函等的）固定路线；照例要出去做的事情","lab":"British English","sc":"regular activities/route","ex":{"en":"Dr Green was on her daily ward rounds.","cn":"格林医生在进行每日一次的巡查病房。"},"pos":"noun"},{"en":"a number of drinks bought by one person for all the others in a group","cn":"（由一人给大家买的）一巡饮料","sc":"drinks","ex":{"en":"a round of drinks","cn":"一巡饮料"},"pos":"noun"},{"en":"a whole slice of bread; sandwiches made from two whole slices of bread","cn":"一整片面包；（两整片面包做的）三明治","lab":"British English","sc":"bread","ex":{"en":"Who's for another round of toast?","cn":"谁还要烤面包片？"},"pos":"noun"},{"en":"a round object or piece of something","cn":"圆形物体；圆块","sc":"circle","ex":{"en":"Cut the pastry into rounds.","cn":"将油酥面团切成一个个圆块。"},"pos":"noun"},{"en":"a short period during which people show their approval of somebody/something by clapping","cn":"一阵","sc":"of applause/cheers","ex":{"en":"There was a great round of applause when the dance ended.","cn":"舞蹈结束的时候，爆发出了一阵热烈的掌声。"},"pos":"noun"},{"en":"a single shot from a gun; a bullet for one shot","cn":"一次射击；一发子弹","sc":"shot","ex":{"en":"They fired several rounds at the crowd.","cn":"他们朝人群开了几枪。"},"pos":"noun"},{"en":"a song for two or more voices in which each sings the same tune but starts at a different time","cn":"轮唱曲","lab":"music","sc":"song","pos":"noun"},{"en":"to go around a corner of a building, a bend in the road, etc.","cn":"绕行；绕过","g":"[transitive]","ex":{"en":"The boat rounded the tip of the island.","cn":"小船绕过岛的尖端。"},"pos":"verb"},{"en":"to make something into a round shape; to form into a round shape","cn":"（使）成圆形；变圆","g":"[transitive, intransitive]","ex":{"en":"She rounded her lips and whistled.","cn":"她撮起嘴唇吹口哨。"},"pos":"verb"},{"en":"to increase or decrease a number to the next highest or lowest whole number","cn":"（将数字调高或调低）使成为整数；把（数字）四舍五入","g":"[transitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…周围;围绕","en":"To be positioned round a place or object means to surround it or be on all sides of it. To move round a place means to go along its edge, back to the point where you started.","ex":{"en":"They were sitting round the kitchen table","cn":"他们正围坐在餐桌旁。"}},{"pos":"PREP 介词","cn":"绕过;到…的另一边","en":"If you move round a corner or obstacle, you move to the other side of it. If you look round a corner or obstacle, you look to see what is on the other side.","ex":{"en":"Suddenly a car came round a corner on the opposite side","cn":"突然，对面的街角处拐过一辆汽车。"}},{"pos":"PREP 介词","cn":"在…各处;遍及;在…附近","en":"You use round to say that something happens in or relates to different parts of a place, or is near a place.","ex":{"en":"He happens to own half the land round here","cn":"他恰好拥有这里一半的土地。"}},{"pos":"ADV 副词","cn":"环绕地;旋转地","en":"If a wheel or object spins round, it turns on its axis.","ex":{"en":"Holes can be worn remarkably quickly by a wheel going round at 60mph","cn":"以每小时60英里的速度前进的车轮很快就会磨出洞来。"}},{"pos":"ADV 副词","cn":"朝反方向地;转身地","en":"If you turn round, you turn so that you are facing or going in the opposite direction.","ex":{"en":"She paused, but did not turn round","cn":"她停了一下，但是并没有转身。"}},{"pos":"ADV 副词","cn":"向不同方向地;四处地","en":"If you move things round, you move them so they are in different places.","ex":{"en":"He will be glad to refurnish where possible, change things round and redecorate","cn":"他会很乐意尽可能添置些家具，把东西挪一挪，然后重新装饰。"}},{"pos":"ADV 副词","cn":"逐一，挨个（传递）","en":"If you hand or pass something round, it is passed from person to person in a group.","ex":{"en":"John handed round the plate of sandwiches.","cn":"约翰把那盘三明治传给大家。"}},{"pos":"ADV 副词","cn":"去，到，至（某人的家）","en":"If you go round to someone's house, you visit them.","ex":{"en":"I think we should go round and tell Kevin to turn his music down","cn":"我觉得我们应该去凯文家让他把音乐的声音调小一些。"}},{"pos":"ADV 副词","cn":"在某处（无所事事）","en":"You use round in informal expressions such as sit round or hang round when you are saying that someone is spending time in a place and is not doing anything very important.","ex":{"en":"As we sat round chatting, I began to think I'd made a mistake","cn":"当我们坐在那里聊天时，我开始认为自己犯了一个错误。"}},{"pos":"PREP 介词","cn":"以…为基础;基于","en":"If something is built or based round a particular idea, that idea is the basis for it.","ex":{"en":"That was for a design built round an existing American engine","cn":"那是用在以现有的一种美国发动机为基础的设计之上的。"}},{"pos":"PREP 介词","cn":"克服;解决","en":"If you get round a problem or difficulty, you find a way of dealing with it.","ex":{"en":"Don't just immediately give up but think about ways round a problem","cn":"不要马上放弃，应该想想解决问题的办法。"}},{"pos":"ADV 副词","cn":"（想法等）转过来，发生改变","en":"If you win someone round, or if they come round, they change their mind about something and start agreeing with you.","ex":{"en":"He did his best to talk me round, but I wouldn't speak to him","cn":"他竭力想要说服我改变主意，但是我不愿意跟他讲话。"}},{"pos":"ADV 副词","cn":"（用于描述以前发生过或定期发生的事情）","en":"You use round in expressions such as this time round or to come round when you are describing something that has happened before or things that happen regularly.","ex":{"en":"In the past, the elections have been marked by hundreds of murders, but this time round the violence has been much more limited","cn":"在过去，这些选举中总是会发生数百起谋杀案，但这一次暴力事件已经非常少了。"}},{"pos":"PREP 介词","cn":"周长;围","en":"You can use round to give the measurement of the outside of something that is shaped like a circle or a cylinder.","ex":{"en":"I'm about two inches larger round the waist.","cn":"我的腰围大概粗了两英寸。"}},{"pos":"ADV 副词","cn":"大约;大概","en":"You use round in front of times or amounts to indicate that they are approximate.","ex":{"en":"I go to bed round 11:00 at night.","cn":"我大约晚上11点上床睡觉。"}},{"pos":"PREP-PHRASE 短语介词","cn":"大约;大概","en":"In spoken English, round about means approximately.","ex":{"en":"Round about one and a half million people died.","cn":"大概有150万人死亡。"}},{"pos":"PHRASE 短语","cn":"处处;所有;整个","en":"You say all round to emphasize that something affects all parts of a situation or all members of a group.","ex":{"en":"It ought to make life much easier all round","cn":"它应该会让生活的方方面面都变得更加方便。"}},{"pos":"PHRASE 短语","cn":"(在脑海里)萦绕，挥之不去","en":"If you say that something is going round and round in your head, you mean that you can't stop thinking about it.","ex":{"en":"It all keeps going round and round in my head till I don't know where I am.","cn":"这一直在我脑海里萦绕，直到我不知身在何处。"}},{"pos":"PHRASE 短语","cn":"全年;一年到头","en":"If something happens all year round, it happens throughout the year.","ex":{"en":"Many of these plants are evergreen, so you can enjoy them all year round","cn":"这些植物中有很多都是四季常青的，所以一年到头都可以观赏。"}},{"pos":"","cn":"","en":"round the corner→see: ; the other way round→see: ;"},{"pos":"N-COUNT 可数名词","cn":"一连串，一系列，一轮(相关的事件，尤指相继发生的事件)","en":"A round of events is a series of related events, especially one which comes after or before a similar series of events.","ex":{"en":"It was agreed that another round of preliminary talks would be held in Peking","cn":"经协商，新一轮的预备会谈将在北京举行。"}},{"pos":"N-COUNT 可数名词","cn":"(比赛的)轮，局，场","en":"In sport, a round is a series of games in a competition. The winners of these games go on to play in the next round, and so on, until only one player or team is left.","ex":{"en":"...in the third round of the Pilkington Cup","cn":"在皮尔金顿杯的第3轮比赛中"}},{"pos":"N-COUNT 可数名词","cn":"(拳击、摔跤比赛的)回合","en":"In a boxing or wrestling match, a round is one of the periods during which the boxers or wrestlers fight.","ex":{"en":"He was declared the victor in the 11th round","cn":"在第11回合中，他被宣布获胜。"}},{"pos":"N-COUNT 可数名词","cn":"(高尔夫球赛的)一场","en":"A round of golf is one game, usually including 18 holes.","ex":{"en":"...two rounds of golf","cn":"两场高尔夫球赛"}},{"pos":"N-COUNT 可数名词","cn":"圆形物","en":"A round is a circular shape.","ex":{"en":"...small fresh rounds of goats' cheese","cn":"新鲜的小块圆形山羊奶酪"}},{"pos":"N-COUNT 可数名词","cn":"一片(面包)；一个（三明治）","en":"A round of bread is a slice of bread. A round of sandwiches is a sandwich made from two slices of bread.","ex":{"en":"...four rounds of toast.","cn":"4片吐司"}},{"pos":"N-COUNT 可数名词","cn":"四处拜访;到处走访","en":"If you do your rounds or your round, you make a series of visits to different places or people, for example as part of your job.","ex":{"en":"The consultants still did their morning rounds","cn":"这些顾问们上午仍然四处走访。"}},{"pos":"N-COUNT 可数名词","cn":"(为在场同伴买的)一巡（饮料）","en":"If you buy a round of drinks, you buy a drink for each member of the group of people that you are with.","ex":{"en":"They sat on the clubhouse terrace, downing a round of drinks","cn":"他们坐在俱乐部会所的露台上，大口喝着别人请的饮料。"}},{"pos":"N-COUNT 可数名词","cn":"一发(子弹);一次（射击）","en":"A round of ammunition is the bullet or bullets released when a gun is fired.","ex":{"en":"...firing 1650 rounds of ammunition during a period of ten minutes.","cn":"在10分钟之内打出了1,650发子弹"}},{"pos":"N-COUNT 可数名词","cn":"一阵（掌声）","en":"If there is a round of applause, everyone claps their hands to welcome someone or to show that they have enjoyed something.","ex":{"en":"Sue got a sympathetic round of applause.","cn":"休得到了一片赞成的掌声。"}},{"pos":"N-COUNT 可数名词","cn":"轮唱曲","en":"In music, a round is a simple song sung by several people in which each person sings a different part of the song at the same time."},{"pos":"PHRASE 短语","cn":"(故事、想法或玩笑)传播，流传，传开","en":"If a story, idea, or joke is going the rounds or doing the rounds, a lot of people have heard it and are telling it to other people.","ex":{"en":"This story was going the rounds 20 years ago.","cn":"20年前，这个故事广为流传。"}},{"pos":"PHRASE 短语","cn":"到各处去;巡回参观","en":"If you make the rounds or do the rounds, you visit a series of different places.","ex":{"en":"After school, I had picked up Nick and Ted and made the rounds of the dry cleaner and the grocery store","cn":"放学以后，我接了尼克和特德，然后又去了干洗店和杂货店。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"圆的;圆形的;球形的","en":"Something that is round is shaped like a circle or ball.","ex":{"en":"She had small feet and hands and a flat, round face.","cn":"她的手脚都很小，脸又扁又圆。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(眼睛)瞪圆的，圆睁的","en":"If someone has round eyes, their eyes are open wide, for example because they are surprised, excited, or afraid.","ex":{"en":"The boy sucked his thumb and stared at Hebburn with huge, round eyes.","cn":"男孩吮吸着拇指，瞪圆了大眼睛盯着赫本。"}},{"pos":"ADJ 形容词","cn":"整数的，不计尾数的(以10的倍数表示)","en":"A round number is a multiple of 10, 100, 1000, and so on. Round numbers are used instead of precise ones to give the general idea of a quantity or proportion.","ex":{"en":"A million pounds seemed a suitably round number.","cn":"100万英镑看起来是一个比较合适的整数。"}},{"pos":"VERB 动词","cn":"绕过;绕行;绕道","en":"If you round a place or obstacle, you move in a curve past the edge or corner of it.","ex":{"en":"The house disappeared from sight as we rounded a corner","cn":"我们绕过街角就看不到那座房子了。"}},{"pos":"VERB 动词","cn":"取整;四舍五入","en":"If you round an amount up or down, or if you round it off, you change it to the nearest whole number or nearest multiple of 10, 100, 1000 and so on.","ex":{"en":"We needed to do decimals to round up and round down numbers","cn":"我们得把小数四舍五入成整数。"}},{"pos":"","cn":"","en":"相关词组：round off round on round up"}]},"examples":[{"en":"She rounded off the tour with a concert at Carnegie Hall.","cn":"她在卡内基大厅举行一场音乐会，以此圆满结束了她的巡回演出。"},{"en":"He rounded on journalists, calling them ‘a pack of vultures’.","cn":"他突然对记者大发雷霆，称他们是一帮乘人之危的家伙。"}]},"roughly":{"media":{"uk":"media/uk/roughly__gb_1.mp3","us":"media/us/roughly__us_1.mp3"},"oxford":{"phon":"ˈrʌfli","pos":"adverb","senses":[{"en":"approximately but not exactly","cn":"大约；大致；差不多","ex":{"en":"Sales are up by roughly 10 per cent.","cn":"销售额上升了大约 10%。"}},{"en":"using force or not being careful and gentle","cn":"粗暴地；粗鲁地","ex":{"en":"He pushed her roughly out of the way.","cn":"他粗暴地把她推到一边。"}},{"en":"in a way that does not leave a smooth surface","cn":"粗糙地；凹凸不平地","ex":{"en":"roughly plastered walls","cn":"灰泥抹得凹凸不平的墙壁"}}]},"examples":[{"en":"Roughly speaking, we receive about fifty letters a week on the subject.","cn":"关于这个问题，粗略地说，我们每周收到大约五十封来信。"},{"en":"We live roughly halfway between here and the coast.","cn":"我们住的地方大致在这里和海滨中间。"}]},"routine":{"media":{"uk":"media/uk/routine__gb_1.mp3","us":"media/us/routine__us_1.mp3"},"oxford":{"phon":"ruːˈtiːn","pos":"noun","senses":[{"en":"the normal order and way in which you regularly do things","cn":"常规；正常顺序","g":"[countable, uncountable]","ex":{"en":"to settle/get/fall into a routine","cn":"形成规律；养成习惯"}},{"en":"a situation in which life is boring because things are always done in the same way","cn":"生活乏味；无聊","g":"[uncountable]","lab":"disapproving","ex":{"en":"She needed a break from routine.","cn":"她需要摆脱一下刻板的生活。"}},{"en":"a series of movements, jokes, etc. that are part of a performance","cn":"（演出中的）一套动作，一系列笑话（等）","g":"[countable]","ex":{"en":"to do/perform a dance routine","cn":"做一套舞蹈动作"}},{"en":"a list of instructions that enable a computer to perform a particular task","cn":"例程；例行程序","g":"[countable]","lab":"computing"},{"en":"done or happening as a normal part of a particular job, situation or process","cn":"常规的；例行公事的；日常的","ex":{"en":"routine enquiries/questions/tests/screening","cn":"常规询问／问题／检测／筛查"},"pos":"adjective"},{"en":"not unusual or different in any way","cn":"平常的；正常的；毫不特别的","ex":{"en":"He died of a heart attack during a routine operation.","cn":"他在一次普通手术中死于心脏病。"},"pos":"adjective"},{"en":"ordinary and boring","cn":"乏味的；平淡的","lab":"disapproving","ex":{"en":"a routine job","cn":"平淡乏味的工作"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"惯例;常规;例行公事","en":"A routine is the usual series of things that you do at a particular time. A routine is also the practice of regularly doing things in a fixed order.","ex":{"en":"The players had to change their daily routine and lifestyle","cn":"这些运动员不得不改变他们的日常生活习惯和方式。"}},{"pos":"ADJ 形容词","cn":"例行的;常规的;惯常的","en":"You use routine to describe activities that are done as a normal part of a job or process.","ex":{"en":"...a series of routine medical tests","cn":"一系列常规的医疗检查"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"普通的;平常的;一般的;乏味的","en":"A routine situation, action, or event is one which seems completely ordinary, rather than interesting, exciting, or different.","ex":{"en":"So many days are routine and uninteresting, especially in winter.","cn":"许多日子都过得平淡乏味，尤其是在冬天。"}},{"pos":"N-VAR 可变名词","cn":"一成不变;平淡乏味","en":"You use routine to refer to a way of life that is uninteresting and ordinary, or hardly ever changes.","ex":{"en":"...the mundane routine of her life","cn":"她平淡乏味的生活"}},{"pos":"N-COUNT 可数名词","cn":"例行程序","en":"A routine is a computer program, or part of a program, that performs a specific function.","ex":{"en":"... an installation routine.","cn":"一个安装程序"}},{"pos":"N-COUNT 可数名词","cn":"（演出中的）一组笑话（或谈话等），一套动作","en":"A routine is a short sequence of jokes, remarks, actions, or movements that forms part of a longer performance.","ex":{"en":"... like a Marx Brothers routine.","cn":"像马克思兄弟风格的搞笑套路"}}]},"examples":[{"en":"Visitors are routinely checked as they enter the building.","cn":"来访者在进入大楼时都要接受例行检查。"},{"en":"The fault was discovered during a routine check.","cn":"这个错误是在一次常规检查中发现的。"}]},"robin":{"media":{"uk":"media/uk/robin__gb_1.mp3","us":"media/us/robin__us_1.mp3"},"oxford":{"phon":"ˈrɒbɪn","pos":"noun","senses":[{"en":"a small brown European bird with a red breast","cn":"欧亚鸲；欧洲知更鸟"},{"en":"a grey American bird with a red breast, larger than a European robin","cn":"旅鸫，美洲知更鸟（毛灰色，胸部红色，比欧亚鸲大）"},{"en":"a first name for boys (usually Robin) or girls (usually Robyn)","cn":"罗宾（男子名常写作 Robin，女子名常写作 Robyn）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸲;知更鸟","en":"A robin is a small brown bird found in Europe. The male has an orangey-red neck and breast."},{"pos":"N-COUNT 可数名词","cn":"鸫","en":"A robin is a brown bird found in North America. The male has a reddish-brown breast. North American robins are larger than European ones, and are a completely different species of bird."}]}},"room":{"media":{"uk":"media/uk/room__gb_1.mp3","us":"media/us/room__us_1.mp3"},"oxford":{"phon":"ruːm","pos":"noun","senses":[{"en":"a part of a building that has its own walls, floor and ceiling and is usually used for a particular purpose","cn":"房间；室","g":"[countable]","sc":"in building","ex":{"en":"I heard him enter the room.","cn":"我听到他进了房间。"}},{"en":"having the number of rooms mentioned","cn":"有…室的；有…个房间的","sc":"-roomed/-room","ex":{"en":"a three-roomed/three-room apartment","cn":"三室的套房"}},{"en":"a bedroom in a hotel, etc.","cn":"客房","g":"[countable]","lab":"British English","sc":"in hotel","ex":{"en":"a double/single room","cn":"双人／单人客房"}},{"en":"a set of two or more rooms that you rent to live in","cn":"（租用的）住所，寓所","g":"[plural]","lab":"British English, old-fashioned，，","sc":"place to live","ex":{"en":"They lived in rooms in Kensington.","cn":"他们住在肯辛顿的出租房间。"}},{"en":"empty space that can be used for a particular purpose","cn":"空间；余地","g":"[uncountable]","sc":"space","ex":{"en":"I'll move the table—it takes up too much room.","cn":"我要挪动一下这张桌子，它太占地方了。"}},{"en":"the possibility of something existing or happening; the opportunity to do something","cn":"可能性；机会","g":"[uncountable]","sc":"possibility","ex":{"en":"He had to be certain. There could be no room for doubt.","cn":"他必须确定无误。不能有任何的疑惑。"}},{"en":"all the people in a room","cn":"房间里所有的人","g":"[singular]","sc":"people","ex":{"en":"The whole room burst into applause.","cn":"屋里的人发出一片掌声。"}},{"en":"to rent a room somewhere; to share a rented room or flat with somebody","cn":"租房；合租","ex":{"en":"She and Nancy roomed together at college.","cn":"她和南希在大学里合住一处。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"房间;屋子;室;房间里的所有人","en":"A room is one of the separate sections or parts of the inside of a building. Rooms have their own walls, ceilings, floors, and doors, and are usually used for particular activities. You can refer to all the people who are in a room as the room .","ex":{"en":"A minute later he excused himself and left the room","cn":"一分钟之后，他说了声抱歉就离开了房间。"}},{"pos":"N-COUNT 可数名词","cn":"私人房间（尤指卧室或办公室）","en":"If you talk about your room, you are referring to the room that you alone use, especially your bedroom at home or your office at work.","ex":{"en":"If you're running upstairs, go to my room and bring down my sweater, please.","cn":"如果你上楼，麻烦到我的房间把我的毛衣拿下来。"}},{"pos":"N-COUNT 可数名词","cn":"(宾馆的)房间","en":"A room is a bedroom in a hotel.","ex":{"en":"Toni booked a room in an hotel not far from Arzfeld.","cn":"托妮在离阿茨费尔德不远的一家宾馆订了一个房间。"}},{"pos":"VERB 动词","cn":"同住;合租","en":"If you room with someone, you share a rented room, apartment, or house with them, for example when you are a student.","ex":{"en":"I had roomed with him in New Haven when we were both at Yale Law School.","cn":"我和他都在耶鲁法学院读书的时候，在纽黑文合租了一个房间。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"空间;空地方","en":"If there is room somewhere, there is enough empty space there for people or things to be fitted in, or for people to move freely or do what they want to.","ex":{"en":"There is usually room to accommodate up to 80 visitors","cn":"那里通常可以住得下80位来客。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"机会;余地;可能性","en":"If there is room for a particular kind of behaviour or action, people are able to behave in that way or to take that action.","ex":{"en":"The intensity of the work left little room for personal grief or anxiety","cn":"高强度的工作使人几乎没空去悲伤或者忧虑。"}},{"pos":"PHRASE 短语","cn":"作出改变的机会;回旋的余地","en":"If you have room for manoeuvre, you have the opportunity to change your plans if it becomes necessary or desirable.","ex":{"en":"With an election looming, he has little room for manoeuvre.","cn":"随着大选临近，他几乎没有什么回旋的余地了。"}},{"pos":"See also:","cn":"","en":"→see: ;"}]},"examples":[{"en":"They were in the next room and we could hear every word they said.","cn":"他们在隔壁房间里，我们可以听到他们说的每一句话。"},{"en":"I'd like to book a room with a view of the lake.","cn":"我想预订一套可以看到湖面景色的客房。"}]},"roaring":{"media":{"uk":"media/uk/roaring__gb_1.mp3","us":"media/us/roaring__us_1.mp3"},"oxford":{"phon":"ˈrɔːrɪŋ","pos":"adjective","senses":[{"en":"making a continuous loud deep noise","cn":"咆哮的；呼啸的；轰鸣的","ex":{"en":"All we could hear was the sound of roaring water.","cn":"我们只能听到汹涌澎湃的涛声。"}},{"en":"burning with a lot of flames and heat","cn":"熊熊燃烧的","ex":{"en":"There was a roaring fire in the grate, piled high with logs.","cn":"炉栅里熊熊燃烧，堆满了木头。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"熊熊燃烧的;炽烈的","en":"A roaring fire has large flames and is sending out a lot of heat."},{"pos":"ADJ 形容词","cn":"(成功)巨大的","en":"If something is a roaring success, it is very successful indeed.","ex":{"en":"The government's first effort to privatize a company has been a roaring success.","cn":"政府首次实行公司私有化的努力获得了巨大的成功。"}},{"pos":"PHRASE 短语","cn":"做成一笔大买卖;售出大批货物;生意兴隆","en":"If someone does a roaring trade in a type of goods, they sell a lot of them.","ex":{"en":"Salesmen of unofficial souvenirs have also been doing a roaring trade.","cn":"出售非官方纪念品的推销员的生意也很红火。"}}]},"examples":[{"en":"All we could hear was the sound of roaring water.","cn":"我们只能听到汹涌澎湃的涛声。"},{"en":"The stallholders were doing a roaring trade in burgers.","cn":"摊贩们的汉堡包生意非常兴旺。"}]},"rotation":{"media":{"uk":"media/uk/rotation__gb_1.mp3","us":"media/us/rotation__us_1.mp3"},"oxford":{"phon":"rəʊˈteɪʃn","pos":"noun","senses":[{"en":"the action of an object moving in a circle around a central fixed point","cn":"旋转；转动","g":"[uncountable]","ex":{"en":"the daily rotation of the earth on its axis","cn":"地球每天的自转"}},{"en":"one complete movement in a circle around a fixed point","cn":"（旋转的）一周，一圈","g":"[countable]","ex":{"en":"This switch controls the number of rotations per minute.","cn":"这个开关控制着每分钟的转数。"}},{"en":"the act of regularly changing the thing that is being used in a particular situation, or of changing the person who does a particular job","cn":"轮换；交替；换班","g":"[uncountable, countable]","ex":{"en":"crop rotation/the rotation of crops (= changing the crop that is grown on an area of land in order to protect the soil)","cn":"庄稼的轮作"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"旋转;转动","en":"Rotation is circular movement. A rotation is the movement of something through one complete circle.","ex":{"en":"...the daily rotation of the earth upon its axis.","cn":"地球每天绕地轴自转"}},{"pos":"N-UNCOUNT 不可数名词","cn":"轮流;轮班","en":"The rotation of a group of things or people is the fact of them taking turns to do a particular job or serve a particular purpose. If people do something in rotation, they take turns to do it.","ex":{"en":"He grew a different crop on the same field five years in a row, what researchers call crop rotation","cn":"他连续5年在同一块地里种植不同的作物，研究人员称之为轮作。"}}]},"examples":[{"en":"Wheat, maize and sugar beet are planted in rotation.","cn":"小麦、玉米和甜菜是轮流种植的。"},{"en":"This switch controls the number of rotations per minute.","cn":"这个开关控制着每分钟的转数。"}]},"rounded":{"media":{"uk":"media/uk/rounded__gb_1.mp3","us":"media/us/rounded__us_1.mp3"},"oxford":{"phon":"ˈraʊndɪd","pos":"adjective","senses":[{"en":"having a round shape","cn":"圆形的","ex":{"en":"a surface with rounded edges","cn":"带圆边的面"}},{"en":"having a wide variety of qualities that combine to produce something pleasant, complete and balanced","cn":"全面的；一应俱全的；完善的","ex":{"en":"a smooth rounded taste","cn":"舒爽醇厚的味道"}},{"en":"produced with the lips in a narrow round position","cn":"圆唇的","lab":"phonetics"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"圆形的;圆润的","en":"Something that is rounded is curved in shape, without any points or sharp edges.","ex":{"en":"...a low rounded hill","cn":"低矮的圆形小山"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全面发展的;多方面的;完善的","en":"You describe something or someone as rounded or well-rounded when you are expressing approval of them because they have a personality which is fully developed in all aspects.","ex":{"en":"...his carefully organised narrative, full of rounded, believable and interesting characters.","cn":"他的叙述结构严谨，不乏形象丰满、真实有趣的人物"}}]},"examples":[{"en":"a smooth rounded taste","cn":"舒爽醇厚的味道"},{"en":"a fully rounded education","cn":"非常全面的教育"}]},"robotics":{"media":{"uk":"media/uk/robotics__gb_1.mp3","us":"media/us/robotics__us_1.mp3"},"oxford":{"phon":"rəʊˈbɒtɪks","pos":"noun","senses":[{"en":"the science of designing and operating robots","cn":"机器人学"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"机器人（设计和制造）学","en":"Robotics is the science of designing and building robots."}]},"examples":[{"en":"Robotics is a rapidly growing field.","cn":""}]},"roll":{"media":{"img":["media/pic/roll_comp.jpg","media/thumb/roll.jpg"],"uk":"media/uk/roll__gb_1.mp3","us":"media/us/roll__us_1.mp3"},"oxford":{"phon":"rəʊl","pos":"verb","senses":[{"en":"to turn over and over and move in a particular direction; to make a round object do this","cn":"（使）翻滚，滚动","g":"[intransitive, transitive]","sc":"turn over","ex":{"en":"The ball rolled down the hill.","cn":"球滚下了山。"}},{"en":"to turn over and over or round and round while remaining in the same place; to make something do this","cn":"（使）原地转圈，原地打转","g":"[intransitive, transitive]","sc":"turn over","ex":{"en":"Her eyes rolled.","cn":"她那双眼睛滴溜溜地转动。"}},{"en":"to turn over to face a different direction; to make somebody/something do this","cn":"（使）翻身，翻转","g":"[intransitive, transitive]","lab":"especially North American English","sc":"turn over","ex":{"en":"She rolled over to let the sun brown her back.","cn":"她翻了个身，让太阳把她的背晒成古铜色。"}},{"en":"to throw dice in a game","cn":"掷（骰子）","g":"[transitive]","lab":"especially North American English","sc":"turn over","ex":{"en":"Each player rolls their dice.","cn":"玩家逐个掷骰子。"}},{"en":"to move smoothly on wheels or as if on wheels; to make something do this","cn":"（使）滚动","g":"[intransitive, transitive]","sc":"move (as if) on wheels","ex":{"en":"The car began to roll back down the hill.","cn":"汽车开始倒着往山下滑。"}},{"en":"to move or flow forward in a steady way","cn":"滚滚而来","g":"[intransitive]","sc":"of clouds/waves","ex":{"en":"Mist was rolling in from the sea.","cn":"薄雾从海上涌来。"}},{"en":"to make something/yourself into the shape of a ball or tube","cn":"使…成球状（或管状）","g":"[transitive, intransitive]","sc":"make ball/tube","ex":{"en":"I rolled the string into a ball.","cn":"我把线绳儿绕成了一个球。"}},{"en":"to make a cigarette yourself by putting tobacco on special paper and forming it into a tube","cn":"卷（香烟）","g":"[transitive]","sc":"make ball/tube","ex":{"en":"He leaned on the table and rolled a cigarette.","cn":"他靠在桌子上，卷了一支烟。"}},{"en":"to fold the edge of a piece of clothing, etc. over and over on itself to make it shorter","cn":"把（衣服的边）卷起来","g":"[transitive]","sc":"fold clothing","ex":{"en":"Roll up your sleeves.","cn":"把你的袖子挽起来。"}},{"en":"to make something flat by pushing something heavy over it","cn":"使平坦；压平","g":"[transitive]","sc":"make something flat","ex":{"en":"Roll the pastry on a floured surface.","cn":"在撒了面粉的面板上将油酥面团擀平。"}},{"en":"to wrap or cover somebody/something/yourself in something","cn":"（用某物）包裹，覆盖","g":"[transitive]","sc":"wrap up","ex":{"en":"Roll the meat in the breadcrumbs.","cn":"用面包屑将肉裹起来。"}},{"en":"to move or make something move from side to side","cn":"（使）摇摆，摇晃","g":"[intransitive, transitive]","sc":"of ship/plane/walk","ex":{"en":"He walked with a rolling gait.","cn":"他摇摇晃晃地走着。"}},{"en":"to make a long continuous sound","cn":"发出持续的声音","g":"[intransitive, transitive]","sc":"make sound","ex":{"en":"rolling drums","cn":"咚咚的鼓声"}},{"en":"when a machine rolls or somebody rolls it, it operates","cn":"启动；开动","g":"[intransitive, transitive]","sc":"machine","ex":{"en":"They had to repeat the scene because the cameras weren't rolling.","cn":"他们只好重新拍摄这个镜头，因为摄影机没有启动。"}},{"en":"to behave in a particular way","cn":"举止；表现","g":"[intransitive]","lab":"informal","sc":"behave","ex":{"en":"She surprised her fans with a completely new look because that's how she rolls.","cn":"她以全新的面貌让粉丝们感到惊讶，因为这就是她的行事风格。"}},{"en":"a small loaf of bread for one person","cn":"小面包条；小圆面包","g":"[countable]","sc":"bread","ex":{"en":"Soup and a roll: £3.50","cn":"汤和一小条面包：3.50 英镑"},"pos":"noun"},{"en":"a long piece of paper, cloth, etc. that has been wrapped around itself or a tube several times so that it forms the shape of a tube","cn":"卷；卷轴","g":"[countable, uncountable]","lab":"British English","sc":"of paper/cloth, etc.","ex":{"en":"a roll of fabric/wrapping paper","cn":"一卷布料／包装纸"},"pos":"noun"},{"en":"a paper tube wrapped around sweets, etc.","cn":"一管","g":"[countable]","lab":"North American English","sc":"of sweets/candy","ex":{"en":"a roll of mints","cn":"一管薄荷糖"},"pos":"noun"},{"en":"an act of rolling the body over and over","cn":"翻滚；打滚","g":"[singular]","sc":"of body","ex":{"en":"The kittens were enjoying a roll in the sunshine.","cn":"那些小猫在阳光下嬉戏打滚。"},"pos":"noun"},{"en":"a physical exercise in which you roll your body on the ground, moving your back and legs over your head","cn":"滚翻；翻跟头","g":"[countable]","sc":"of body","ex":{"en":"a forward/backward roll","cn":"前／后滚翻"},"pos":"noun"},{"en":"the act of moving from side to side so that one side is higher than the other","cn":"摇晃；摇荡","g":"[uncountable]","sc":"of ship/plane","pos":"noun"},{"en":"an area of too much fat on your body, especially around the middle part","cn":"（尤指腰部的）赘肉","g":"[countable]","sc":"of fat","ex":{"en":"Rolls of fat hung over his belt.","cn":"一堆肥肉坠在他的腰带上。"},"pos":"noun"},{"en":"an official list of names","cn":"花名册；名单","g":"[countable]","sc":"list of names","ex":{"en":"the electoral roll (= a list of all the people who can vote in an election)","cn":"选民名册"},"pos":"noun"},{"en":"a deep continuous sound","cn":"隆隆声；持续的轰鸣声","g":"[countable]","sc":"sound","ex":{"en":"the distant roll of thunder","cn":"远处隆隆的雷声"},"pos":"noun"},{"en":"an act of rolling a dice","cn":"掷骰子","g":"[countable]","sc":"of dice","ex":{"en":"The order of play is decided by the roll of a dice.","cn":"比赛顺序是通过掷骰子决定的。"},"pos":"noun"},{"en":"a sound, usually a /r/, produced by making the tongue vibrate against a part of the mouth","cn":"颤音","g":"[countable]","lab":"phonetics","sc":"phonetics","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)滚;(使)滚动","en":"When something rolls or when you roll it, it moves along a surface, turning over many times.","ex":{"en":"The ball rolled into the net","cn":"球滚进了网中。"}},{"pos":"VERB 动词","cn":"(身体)滚动，打滚","en":"If you roll somewhere, you move on a surface while lying down, turning your body over and over, so that you are sometimes on your back, sometimes on your side, and sometimes on your front.","ex":{"en":"When I was a little kid I rolled down a hill and broke my leg","cn":"我小时候从一座山坡上滚了下来，把腿摔断了。"}},{"pos":"VERB 动词","cn":"(车辆)慢慢开动，缓缓行进","en":"When vehicles roll along, they move along slowly.","ex":{"en":"The lorry quietly rolled forward.","cn":"卡车静静地缓慢前行。"}},{"pos":"VERB 动词","cn":"(机器)转动，运转，工作","en":"If a machine rolls, it is operating.","ex":{"en":"He slipped and fell on an airplane gangway as the cameras rolled","cn":"在摄像时他不慎滑倒在飞机座位间的通道上。"}},{"pos":"VERB 动词","cn":"(液体)滚落，滑落","en":"If drops of liquid roll down a surface, they move quickly down it.","ex":{"en":"She looked at Ginny and tears rolled down her cheeks.","cn":"她看着金尼，泪水滑落脸庞。"}},{"pos":"VERB 动词","cn":"卷;绕;使成筒状（或球状）","en":"If you roll something flexible into a cylinder or a ball, you form it into a cylinder or a ball by wrapping it several times around itself or by shaping it between your hands.","ex":{"en":"He took off his sweater, rolled it into a pillow and lay down on the grass","cn":"他脱下毛衣，将它卷成一个枕头，然后在草地上躺了下来。"}},{"pos":"N-COUNT 可数名词","cn":"卷;卷轴","en":"A roll of paper, plastic, cloth, or wire is a long piece of it that has been wrapped many times around itself or around a tube.","ex":{"en":"The photographers had already shot a dozen rolls of film.","cn":"摄影师们已经照了一打胶卷了。"}},{"pos":"VERB 动词","cn":"摇(车窗);卷（窗帘等)","en":"If you roll up something such as a car window or a blind, you cause it to move upwards by turning a handle. If you roll it down, you cause it to move downwards by turning a handle.","ex":{"en":"In mid-afternoon, shopkeepers began to roll down their shutters","cn":"下午三时左右，店主们开始放下百叶窗。"}},{"pos":"V-ERG 及物/不及物动词","cn":"转动(眼睛)；(眼珠)骨碌碌地转","en":"If you roll your eyes or if your eyes roll, they move round and upwards. People sometimes roll their eyes when they are frightened, bored, or annoyed.","ex":{"en":"People may roll their eyes and talk about overprotective, interfering grandmothers","cn":"人们可能会翻着白眼谈论那些溺爱儿孙、样样都要插手的祖母。"}},{"pos":"N-COUNT 可数名词","cn":"（一人份的）小圆面包，面包卷","en":"A roll is a small piece of bread that is round or long and is made to be eaten by one person. Rolls can be eaten plain, with butter, or with a filling.","ex":{"en":"He spread butter on a roll.","cn":"他把黄油抹在小圆面包上。"}},{"pos":"N-COUNT 可数名词","cn":"（鼓的）咚咚声,隆隆声,持续的轰鸣声","en":"A roll of drums is a long, low, fairly loud sound made by drums.","ex":{"en":"As the town clock struck two, they heard the roll of drums.","cn":"当小镇的时钟敲响两点钟时，他们听到了隆隆的鼓声。"}},{"pos":"N-COUNT 可数名词","cn":"名单;名册","en":"A roll is an official list of people's names.","ex":{"en":"...the electoral roll.","cn":"选民名单"}},{"pos":"PHRASE 短语","cn":"连连成功;连交好运","en":"If someone is on a roll, they are having great success which seems likely to continue.","ex":{"en":"I made a name for myself and I was on a roll, I couldn't see anything going wrong.","cn":"我靠自己的能力成名了，接二连三地获得成功，我觉得一切似乎一帆风顺。"}},{"pos":"PHRASE 短语","cn":"盼望;期待","en":"If you say roll on something, you mean that you would like it to come soon, because you are looking forward to it.","ex":{"en":"Roll on the day someone develops an effective vaccine against malaria.","cn":"盼望有一天有人会研制出一种能有效预防疟疾的疫苗。"}},{"pos":"PHRASE 短语","cn":"集于一身;融为一体","en":"If something is several things rolled into one, it combines the main features or qualities of those things.","ex":{"en":"Experts claimed that teachers had to be Einstein, Marie Curie and Linford Christie rolled into one to help children grasp the new national curriculum","cn":"专家们称老师必须集爱因斯坦、居里夫人和林弗德·克里斯蒂的本领于一身，才能帮助孩子们掌握新的国家课程大纲。"}},{"pos":"","cn":"","en":"to start the ball rolling→see: ; heads will roll→see: ;"},{"pos":"","cn":"","en":"相关词组：roll back roll in roll up"}]},"examples":[{"en":"They had to repeat the scene because the cameras weren't rolling.","cn":"他们只好重新拍摄这个镜头，因为摄影机没有启动。"},{"en":"She rolled over to let the sun brown her back.","cn":"她翻了个身，让太阳把她的背晒成古铜色。"}]},"rolls":{"oxford":{"phon":"ˌrəʊlz ˈrɔɪs","pos":"noun","senses":[{"en":"a large, comfortable and expensive make of car made by a company in the UK","cn":"劳斯莱斯汽车（英国一种大型豪华轿车）"},{"en":"( BrE ) something that is thought of as an example of the highest quality of a type of thing","cn":"最优质的品种；最优品"}]}},"root":{"media":{"img":["media/pic/root_vegetables_comp.jpg","media/thumb/carrot.jpg"],"uk":"media/uk/root__gb_1.mp3","us":"media/us/root__us_1.mp3"},"oxford":{"phon":"ruːt","pos":"noun","senses":[{"en":"the part of a plant that grows under the ground and takes in water and minerals that it sends to the rest of the plant","cn":"根；根茎","g":"[countable]","sc":"of plant","ex":{"en":"deep spreading roots","cn":"扎得很深的根"}},{"en":"the part of a hair, tooth, nail or tongue that attaches it to the rest of the body","cn":"根；根部","g":"[countable]","sc":"of hair/tooth/nail","ex":{"en":"hair that is blonde at the ends and dark at the roots","cn":"发梢金黄而发根褐色的头发"}},{"en":"the main cause of something, such as a problem or difficult situation","cn":"根源；起因","g":"[countable, usually singular]","sc":"main cause of problem","ex":{"en":"Money, or love of money, is said to be the root of all evil.","cn":"有人说钱和爱钱是万恶之源。"}},{"en":"the origin or basis of something","cn":"起源；基础；根基","g":"[countable, usually plural]","sc":"origin","ex":{"en":"Flamenco may have its roots in Arabic music.","cn":"弗拉门科可能起源于阿拉伯音乐。"}},{"en":"the feelings or connections that you have with a place because you have lived there or your family came from there","cn":"根（指与出生地或原籍相关联的情感或联系）","g":"[plural]","sc":"connection with place","ex":{"en":"I'm proud of my Italian roots.","cn":"我为我的意大利血统感到骄傲。"}},{"en":"the part of a word that has the main meaning and that its other forms are based on; a word that other words are formed from","cn":"词根","g":"[countable]","lab":"linguistics","sc":"of word","ex":{"en":"‘Comfort’ is the root of ‘comfortable’, ‘comfortably’, ‘discomfort’ and ‘uncomfortable’.","cn":"comfort 是 comfortable、comfortably、discomfort 和 uncomfortable 的词根。"}},{"en":"a quantity which, when multiplied by itself a particular number of times, produces another quantity","cn":"方根；根","g":"[countable]","sc":"mathematics"},{"en":"to grow roots; to cause or encourage a plant to grow roots","cn":"（使）生根","g":"[intransitive, transitive]","sc":"of plants","pos":"verb"},{"en":"to search for something by moving things or turning things over","cn":"翻寻","g":"[intransitive]","sc":"search","ex":{"en":"pigs rooting for food","cn":"拱土觅食的猪"},"pos":"verb"},{"en":"to have sex with somebody","cn":"（与某人）发生性关系","g":"[intransitive, transitive]","lab":"Australian English, New Zealand English, taboo, slang，，，，，，","sc":"sex","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"根;根茎","en":"The roots of a plant are the parts of it that grow under the ground.","ex":{"en":"...the twisted roots of an apple tree.","cn":"苹果树盘绕的根"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)生根成长","en":"If you root a plant or cutting or if it roots, roots form on the bottom of its stem and it starts to grow.","ex":{"en":"Most plants will root in about six to eight weeks","cn":"大多数植物都会在6到8周内生根。"}},{"pos":"ADJ 形容词","cn":"(蔬菜、作物等)块根的，根茎可食用的","en":"Root vegetables or root crops are grown for their roots which are large and can be eaten.","ex":{"en":"...root crops such as carrots and potatoes.","cn":"诸如胡萝卜和马铃薯之类的块根作物"}},{"pos":"N-COUNT 可数名词","cn":"(头发或牙齿的)根，根部","en":"The root of a hair or tooth is the part of it that is underneath the skin.","ex":{"en":"...decay around the roots of teeth.","cn":"牙根周围的腐蚀"}},{"pos":"N-PLURAL 复数名词","cn":"根脉;祖籍;血统;根基","en":"You can refer to the place or culture that a person or their family comes from as their roots .","ex":{"en":"I am proud of my Brazilian roots","cn":"我为我的巴西血统感到自豪。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"根音乐（受传统文化强烈影响的流行音乐，尤指雷盖音乐)","en":"Roots is used to refer to pop music, especially reggae, that is strongly influenced by the traditional music of the culture that it originally came from.","ex":{"en":"...superb roots reggae by the likes of Little Roy and Wailing Souls.","cn":"像小罗伊、“哭泣灵魂”等这一类音乐人表演的极棒的老根雷盖乐"}},{"pos":"N-COUNT 可数名词","cn":"(问题、困境等的)根源，起因，祸根","en":"You can refer to the cause of a problem or of an unpleasant situation as the root of it or the roots of it.","ex":{"en":"We got to the root of the problem","cn":"我们找到了问题的根源。"}},{"pos":"N-COUNT 可数名词","cn":"词根","en":"The root of a word is the part that contains its meaning and to which other parts can be added.","ex":{"en":"The word 'secretary' comes from the same Latin root as the word 'secret'.","cn":"单词secretary和secret有同样的拉丁词根。"}},{"pos":"VERB 动词","cn":"翻找;搜寻","en":"If you root through or in something, you search for something by moving other things around.","ex":{"en":"She rooted through the bag, found what she wanted, and headed toward the door","cn":"她在包里翻了一阵，找到了想要的东西，然后朝门口走去。"}},{"pos":"PHRASE 短语","cn":"完全地;彻底地","en":"If something has been completely changed or destroyed, you can say that it has been changed or destroyed root and branch .","ex":{"en":"The forces of National Socialism were transforming Germany root and branch","cn":"纳粹主义势力当时正在彻底改变德国。"}},{"pos":"PHRASE 短语","cn":"扎根;定居;安家","en":"If someone puts down roots, they make a place their home, for example by taking part in activities there or by making a lot of friends there.","ex":{"en":"When they got to Montana, they put down roots and built a life.","cn":"到了蒙大拿后，他们便在那里扎根并过上了新生活。"}},{"pos":"PHRASE 短语","cn":"(想法、信念或风俗)深入人心，根深蒂固","en":"If an idea, belief, or custom takes root, it becomes established among a group of people.","ex":{"en":"Time would be needed for democracy to take root","cn":"民主观念要深入人心需要时间。"}},{"pos":"","cn":"","en":"相关词组：root around root for root out"}]},"examples":[{"en":"‘Walk’ is the root of ‘walks’, ‘walked’, ‘walking’ and ‘walker’. * walk","cn":"是 walks、walked、walking 和 walker 的词根。"},{"en":"After 20 years in America, I still feel my roots are in England.","cn":"尽管在美国生活了 20 年，我还是觉得我的根在英国。"}]},"rooster":{"media":{"uk":"media/uk/rooster__gb_1.mp3","us":"media/us/rooster__us_1.mp3","img":["media/ldoce/img/rooster.jpg"]},"oxford":{"phon":"ˈruːstə(r)","pos":"noun","senses":[{"en":"an adult male chicken","cn":"公鸡；雄鸡"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雄鸡;公鸡","en":"A rooster is an adult male chicken."}]}},"rows":{"oxford":{"phon":"rəʊ","pos":"noun","senses":[{"en":"a number of people standing or sitting next to each other in a line; a number of objects arranged in a line","cn":"一排；一列；一行"},{"en":"a line of seats in a cinema/movie theater, etc. （","cn":"剧院、电影院等的）一排座位"}]}},"rose":{"media":{"img":["media/ldoce/img/rose.jpg","media/pic/flowerlabels_flowers_comp.jpg"],"uk":"media/uk/rose__gb_2.mp3","us":"media/us/rose__us_2.mp3"},"oxford":{"phon":"rəʊz","pos":"noun","senses":[{"en":"a flower with a sweet smell that grows on a bush with thorns (= sharp points) on its stems","cn":"玫瑰（花）；蔷薇（花）","g":"[countable]","ex":{"en":"a bunch of red roses","cn":"一束红玫瑰花"}},{"en":"a pink colour","cn":"粉红色","g":"[uncountable]"},{"en":"a piece of metal or plastic with small holes in it that is attached to the end of a pipe or watering can so that the water comes out in a fine spray when you are watering plants","cn":"（水管或喷壶的）莲蓬式喷嘴","g":"[countable]"},{"en":"a round object that is fixed to the ceiling of a room for the wires of an electric light to go through","cn":"（天花板或顶棚的）灯线盒","lab":"specialist"},{"en":"pink in colour","cn":"粉红色的；玫瑰色的","ex":{"en":"The walls were rose pink.","cn":"墙壁是玫瑰粉色的。"},"pos":"adjective"},{"en":"a first name for girls","cn":"罗泽（女子名）","pos":""},{"en":"a light pink wine","cn":"玫瑰红葡萄酒；粉红葡萄酒","ex":{"en":"a bottle of rosé","cn":"一瓶玫瑰红葡萄酒"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Rose is the past tense of rise ."},{"pos":"N-COUNT 可数名词","cn":"玫瑰花;蔷薇花","en":"A rose is a flower, often with a pleasant smell, which grows on a bush with stems that have sharp points called thorns on them.","ex":{"en":"She bent to pick a red rose.","cn":"她弯腰去摘一朵红玫瑰。"}},{"pos":"N-COUNT 可数名词","cn":"蔷薇;玫瑰","en":"A rose is bush that roses grow on.","ex":{"en":"Prune rambling roses when the flowers have faded.","cn":"花朵凋谢后要剪除杂生的玫瑰枝。"}},{"pos":"COLOUR 颜色词","cn":"玫瑰色;红粉色","en":"Something that is rose is reddish-pink in colour.","ex":{"en":"...the rose and violet hues of a twilight sky.","cn":"黄昏时天空中玫瑰色和紫罗兰色的云霞"}},{"pos":"N-COUNT 可数名词","cn":"（喷壶或水管的）莲蓬头喷嘴","en":"A rose is a device with very small holes in it that fits onto the end of a hosepipe or watering can. The water comes out of the rose in a fine spray so that you can water plants."},{"pos":"PHRASE 短语","cn":"尽善尽美;尽如人意","en":"If you say that a situation is not a bed of roses, you mean that it is not as pleasant as it seems, and that there are some unpleasant aspects to it.","ex":{"en":"We all knew that life was unlikely to be a bed of roses back in England.","cn":"我们都知道回到英格兰以后的生活不太可能幸福完美。"}},{"pos":"PHRASE 短语","cn":"一切进展顺利;一帆风顺","en":"If you say that everything is coming up roses for someone, you mean that everything is going well for them.","ex":{"en":"Earlier this year, everything was coming up roses for them. Their 'Going Blank Again' album was selling well, and their British tour was a virtual sell-out.","cn":"今年年初，他们一切都很顺利。专辑《再次一片空白》十分畅销，英国巡演的票也几乎销售一空。"}}]},"examples":[{"en":"a climbing/rambling rose","cn":"攀缘的/蔓生的蔷薇"},{"en":"a rose bush/garden","cn":"玫瑰丛；玫瑰园"}]},"roadside":{"media":{"uk":"media/uk/roadside__gb_1.mp3","us":"media/us/roadside__us_1.mp3"},"oxford":{"phon":"ˈrəʊdsaɪd","pos":"noun","senses":[{"en":"the edge of the road","cn":"路边；路旁","ex":{"en":"a roadside cafe","cn":"路边咖啡店"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"路旁;路边","en":"The roadside is the area at the edge of a road.","ex":{"en":"Bob was forced to leave the car at the roadside and run for help","cn":"鲍勃被迫把车停在路边，然后跑去求助了。"}}]},"examples":[{"en":"We parked by the roadside.","cn":"我们将车停放在路旁。"},{"en":"a roadside cafe","cn":"路边咖啡店"}]},"rocks":{"oxford":{"phon":"rɒk","pos":"noun","senses":[{"en":"the hard solid material that forms part of the surface of the earth and some other planets","cn":"岩石"},{"en":"a mass of rock standing above the earth's surface or in the sea/ocean","cn":"石山；礁石"}]}},"robbers":{"oxford":{"phon":"ˈrɒbə(r)","pos":"noun","senses":[{"en":"a person who steals from a person or place, especially using violence or threats","cn":"强盗；盗贼；抢劫犯"}]}},"rolled":{"oxford":{"phon":"rəʊl","pos":"noun","senses":[{"en":"a long piece of paper, cloth, film, etc. that has been wrapped around itself or a tube several times so that it forms the shape of a tube","cn":"卷；卷轴"},{"en":"( NAmE ) a paper tube wrapped around sweets/candy, etc.","cn":"一管"}]}},"roundsmen":{"oxford":{"phon":"ˈraʊndzmən","pos":"noun","senses":[{"en":"a person who delivers things to people in a particular area （","cn":"特定区域的）送货员"},{"en":"( NAmE ) the police officer in charge of a group of officers that is moving around an area （","cn":"管区）巡警长"}]}},"rooms":{"oxford":{"phon":"ruːm","pos":"noun","senses":[{"en":"a part of a building that has its own walls, floor and ceiling and is usually used for a particular purpose","cn":"房间；室"},{"en":"( in adjectives","cn":"构成形容词 ) having the number of rooms mentioned 有 … 室的；有 … 个房间的"}]}},"robed":{"oxford":{"phon":"rəʊb","pos":"noun","senses":[{"en":"a long loose outer piece of clothing, especially one worn as a sign of rank or office at a special ceremony","cn":"袍服，礼袍（常于典礼中穿着以显示身分）"},{"en":"( formal ) to dress sb/yourself in long loose clothes or in the way mentioned （","cn":"给某人）穿上礼袍"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41robed.mp3","us":"media/ldoce/hwd/ame/e/ld41robed.mp3"},"examples":[{"en":"a man robed in black","cn":""}]},"rounds":{"oxford":{"phon":"raʊnd","pos":"adjective","senses":[{"en":"shaped like a circle or a ball","cn":"圆形的；环形的；球形的"},{"en":"having a curved shape","cn":"弧形的；圆弧的"}]}},"roles":{"oxford":{"phon":"rəʊl","pos":"noun","senses":[{"en":"the function or position that sb has or is expected to have in an organization, in society or in a relationship","cn":"职能；地位；角色"},{"en":"an actor's part in a play, film/movie, etc. （","cn":"演员的）角色"}]}},"rocking":{"oxford":{"phon":"rɒk","pos":"noun","senses":[{"en":"the hard solid material that forms part of the surface of the earth and some other planets","cn":"岩石"},{"en":"a mass of rock standing above the earth's surface or in the sea/ocean","cn":"石山；礁石"}]}},"routes":{"oxford":{"phon":"ruːt","pos":"noun","senses":[{"en":"a way that you follow to get from one place to another","cn":"路线；路途"},{"en":"a fixed way along which a bus, train, etc. regularly travels or goods are regularly sent （","cn":"公共汽车和列车等的）常规路线，固定线路"}]}},"ropes":{"oxford":{"phon":"rəʊp","pos":"noun","senses":[{"en":"very strong thick string made by twisting thinner strings, wires, etc. together","cn":"粗绳；线缆；绳索"},{"en":"the fence made of rope that is around the edge of the area where a boxing or wrestling match takes place （","cn":"拳击或摔跤场四周的）围绳，圈绳"}]}},"romantics":{"oxford":{"phon":"rəʊˈmæntɪk","pos":"adjective","senses":[{"en":"connected or concerned with love or a sexual relationship","cn":"浪漫的；爱情的；情爱的"},{"en":"showing feelings of love","cn":"多情的；表达爱情的"}]}},"roamed":{"oxford":{"phon":"rəʊm","pos":"verb","senses":[{"en":"to walk or travel around an area without any definite aim or direction","cn":"徜徉；闲逛；漫步"},{"en":"to move slowly over every part of sb/sth （","cn":"缓慢地）扫遍，摸遍"}]}},"roads":{"oxford":{"phon":"rəʊd","pos":"noun","senses":[{"en":"a hard surface built for vehicles to travel on","cn":"路；道路；公路"},{"en":"used in names of roads, especially in towns （","cn":"用于道路名称，尤指城镇的）路"}]}},"roofs":{"oxford":{"phon":"ruːf","pos":"noun","senses":[{"en":"the structure that covers or forms the top of a building or vehicle","cn":"顶部；屋顶；车顶"},{"en":"( in adjectives","cn":"构成形容词 ) having the type of roof mentioned 有 … 顶的"}]}},"rota":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"值班表;值勤表;勤务薄","en":"A rota is a list which gives details of the order in which different people have to do a particular job.","ex":{"en":"I suggest that you work out a careful rota which will make it clear who tidies the room on which day.","cn":"我建议你制定一个详细的值班表，明确哪一天由谁整理房间。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a list that shows when each person in a group must do a particular job","cn":"值勤表﹐勤务表"}]},"collocations":{"phrases":["ADJ. daily, weekly, etc. | duty | cleaning","VERB + ROTA have | draw up, work out I've been asked to draw up the cleaning rota.","ROTA + NOUN scheme, system","PREP. on the ~ | ~ for Are you on the rota for cooking?","PHRASES on a rota basis We share the babysitting duties on a rota basis."]},"media":{"uk":"media/ldoce/hwd/bre/0/rota0205.mp3","us":"media/ldoce/hwd/ame/3/ld41rota.mp3"},"examples":[{"en":"Dave organized a cleaning rota.","cn":"戴夫安排了打扫卫生轮值表。"},{"en":"a cleaning rota","cn":"卫生轮值表"}],"oxford":{"phon":"ˈrəʊtə","pos":"noun","senses":[{"en":"a list of tasks that need to be done and the people who will do them in turn","cn":"勤务轮值表","ex":{"en":"Dave organized a cleaning rota.","cn":"戴夫排好了打扫卫生轮值表。"}}]}},"roadblock":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(警方或军队设置的)路障","en":"When the police or the army put a roadblock across a road, they stop all the traffic going through, for example because they are looking for a criminal.","ex":{"en":"The city police set up roadblocks to check passing vehicles.","cn":"该市警察设置了路障以检查过往车辆。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where the police are stopping traffic 〔","cn":"警方设置的〕路障"},{"en":"something that stops the progress of a plan","cn":"障碍"}]},"collocations":{"phrases":["ADJ. army, police","VERB + ROADBLOCK erect, set up Police have set up a roadblock on the road to London. | remove","PREP. at a/the ~ They were stopped at a roadblock leaving the city. | through a/the ~ The truck drove through the roadblock at 100 mph."]},"media":{"uk":"media/ldoce/hwd/bre/1/roadblock0205.mp3","us":"media/ldoce/hwd/ame/e/roadblock.mp3"},"examples":[{"en":"The police have set up roadblocks to try and catch the two men.","cn":"警方设置了路障﹐要抓捕那两个人。"},{"en":"mental roadblocks that get in the way of success","cn":"妨碍成功的心理障碍"}],"oxford":{"phon":"ˈrəʊdblɒk","pos":"noun","senses":[{"en":"a barrier put across the road by the police or army so that they can stop and search vehicles","cn":"路障","ex":{"en":"The police set up a roadblock on the bridge.","cn":"警察在桥上设置了路障。"}},{"en":"something that stops a plan from going ahead","cn":"障碍","lab":"North American English","ex":{"en":"This bill would create a roadblock for women.","cn":"这一法案会对妇女形成障碍。"}}]}},"roundabout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（交通）环岛;环形交叉路口","en":"A roundabout is a circular structure in the road at a place where several roads meet. You drive round it until you come to the road that you want."},{"pos":"N-COUNT 可数名词","cn":"旋转木马","en":"A roundabout at a fair is a large, circular mechanical device with seats, often in the shape of animals or cars, on which children sit and go round and round."},{"pos":"N-COUNT 可数名词","cn":"（儿童坐的）旋转圆台","en":"A roundabout in a park or school play area is a circular platform that children sit or stand on. People push the platform to make it spin round."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(路线)迂回的，绕弯的，绕远的","en":"If you go somewhere by a roundabout route, you do not go there by the shortest and quickest route.","ex":{"en":"He left today on a roundabout route for Jordan and is also due soon in Egypt.","cn":"他今天启程绕道去约旦，用不了多久还会去埃及。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(说话或做事)迂回的，转弯抹角的，不直截了当的","en":"If you do or say something in a roundabout way, you do not do or say it in a simple, clear, and direct way.","ex":{"en":"We made a bit of a fuss in a roundabout way.","cn":"我们拐弯抹角地发了点牢骚。"}},{"pos":"","cn":"","en":"round about→see: ; swings and roundabouts→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if one thing cancels out another, it has an opposite effect to it, so that the situation does not change","cn":""},{"en":"if something such as a cost or a sum of money offsets another cost, sum etc, it has an opposite effect so that the situation remains unchanged","cn":""},{"en":"to have an equal and opposite effect to something such as a change, an influence, or a feeling","cn":""}]},"collocations":{"phrases":["VERB + ROUNDABOUT enter | get off, leave Leave the roundabout at the second exit. | drive/go around/round","PREP. at the ~ At the roundabout, turn right. | on the ~ There was a lot of traffic on the roundabout."]},"media":{"uk":"media/ldoce/hwd/bre/e/roundabout_n0205.mp3","us":"media/ldoce/hwd/ame/8/ld41roundabout.mp3","img":["media/thumb/roundabout.jpg"]},"examples":[{"en":"He told us, in a very roundabout way, that he was thinking of leaving.","cn":"他拐弯抹角地对我们说他想走了。"},{"en":"It was a difficult and roundabout trip.","cn":"这是一次艰难而曲折的旅行。"}],"oxford":{"phon":"ˈraʊndəbaʊt","pos":"noun","senses":[{"en":"a place where two or more roads meet, forming a circle that all traffic must go around in the same direction","cn":"（交通）环岛","lab":"North American English","ex":{"en":"At the roundabout, take the second exit.","cn":"到环岛后，走第二个出口。"}},{"en":"a round platform for children to play on in a park, etc. that is pushed round while the children are sitting on it","cn":"（游乐设施）旋转平台","lab":"North American English"},{"en":"a round platform with model horses, cars, etc. that turns around and around and that children ride on at a fairground","cn":"旋转木马","lab":"British English"},{"en":"not done or said using the shortest, simplest or most direct way possible","cn":"迂回的；间接的；兜圈子的","ex":{"en":"It was a difficult and roundabout trip.","cn":"这是一次艰难而曲折的旅行。"},"pos":"adjective"}]}},"robbery":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"抢劫;劫掠","en":"Robbery is the crime of stealing money or property from a bank, shop, or vehicle, often by using force or threats.","ex":{"en":"The gang members committed dozens of armed robberies","cn":"这个帮派的成员犯下了数十宗持械抢劫案。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of stealing money or other things from a bank, shop etc, especially by using threats or violence","cn":""},{"en":"the crime of stealing something, especially when the person they are stolen from is not present","cn":""},{"en":"the crime of entering a house or other building illegally and stealing things","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A person who steals money from a convenience store by claiming to have a gun under his shirt is guilty of robbery , or using a violent threat to take something that doesn't belong to him."}]},"collocations":{"phrases":["ADJ. attempted, bungled, failed | armed | bank, highway, street","VERB + ROBBERY commit, take part in","ROBBERY + NOUN attempt","PHRASES robbery with violence He was sentenced to four years in prison for robbery with violence. • Note at CRIME (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/b/ld44_robbery.mp3","us":"media/ldoce/hwd/ame/b/ld44_robbery.mp3"},"examples":[{"en":"There has been a spate of robberies in the area recently.","cn":"最近这一地区接连发生了多起抢劫案。"},{"en":"armed robbery (= using a gun, knife, etc.)","cn":"持械抢劫"}],"oxford":{"phon":"ˈrɒbəri","pos":"noun","senses":[{"en":"the crime of stealing money or goods from a bank, shop, person, etc., especially using violence or threats","cn":"盗窃；抢劫；掠夺","lab":"British English","ex":{"en":"armed robbery (= using a gun, knife, etc.)","cn":"持械抢劫"}}]}},"royalty":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"王室;皇族","en":"The members of royal families are sometimes referred to as royalty .","ex":{"en":"Royalty and government leaders from all around the world are gathering in Japan.","cn":"世界各国的王室成员和政府首脑齐聚日本。"}},{"pos":"N-PLURAL 复数名词","cn":"(作家、音乐家等的)版税","en":"Royalties are payments made to authors and musicians when their work is sold or performed. They usually receive a fixed percentage of the profits from these sales or performances.","ex":{"en":"I lived on about £3,000 a year from the royalties on my book.","cn":"我靠着写书得来的每年约3,000英镑的版税生活。"}},{"pos":"N-COUNT 可数名词","cn":"(发明、创意、财产等的)使用费","en":"Payments made to someone whose invention, idea, or property is used by a commercial company can be referred to as royalties .","ex":{"en":"The royalties enabled the inventor to re-establish himself in business.","cn":"专利使用费让这位发明家得以再次立足于商界。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"members of a royal family","cn":"王室[王族]成员"},{"en":"a payment made to the writer of a book or piece of music depending on how many books etc are sold, or to someone whose idea, invention etc is used by someone else to make money 〔","cn":"付给书或乐曲作者的〕版税﹔〔发明等的〕使用费"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Royalty is a good word for describing a family of kings, queens, princes, and princesses. If you are in the music business, you may expect a payment, or royalty every time your song is played. How's that for royal treatment?"}]},"collocations":{"phrases":["ADJ. advance","VERB + ROYALTY pay | earn, get, receive | charge","ROYALTY + NOUN cheque, payment","PREP. in ~s She earns a lot in royalties. | ~ from/on He has received royalties on previous inventions.","PHRASES an advance on royalties 2 members of the royal family","ADJ. minor","PHRASES in the presence of royalty She behaved as if she were in the presence of royalty."]},"media":{"uk":"media/ldoce/hwd/bre/0/royalty0205.mp3","us":"media/ldoce/hwd/ame/d/royalty.mp3"},"examples":[{"en":"All royalties from the album will go to charity.","cn":"这张音乐专辑的全部版税收入将捐给慈善机构。"},{"en":"The gala evening was attended by royalty and politicians.","cn":"王室成员和政坛要人参加了这个晚会。"}],"oxford":{"phon":"ˈrɔɪəlti","pos":"noun","senses":[{"en":"one or more members of a royal family","cn":"王室成员","g":"[uncountable]","lab":"figurative","ex":{"en":"The gala evening was attended by royalty and politicians.","cn":"王室成员和政坛要人参加了这个晚会。"}},{"en":"a sum of money that is paid to somebody who has written a book, piece of music, etc. each time that it is sold or performed","cn":"版税","g":"[countable, usually plural]","ex":{"en":"All royalties from the album will go to charity.","cn":"这张音乐专辑的全部版税收入将捐给慈善机构。"}},{"en":"a sum of money that is paid by an oil or mining company to the owner of the land that they are working on","cn":"矿区土地使用费（由采矿或石油公司等付给土地所有人）","g":"[countable, usually plural]"}]}},"roam":{"collins":{"senses":[{"pos":"VERB 动词","cn":"漫步;漫游;游荡;闲逛","en":"If you roam an area or roam around it, you wander or travel around it without having a particular purpose.","ex":{"en":"Barefoot children roamed the streets","cn":"光脚丫的孩子们在街上游荡。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go from one place to another, especially places that are far apart","cn":""},{"en":"to go somewhere – often used instead of travel","cn":""},{"en":"to travel to work or school","cn":""}]},"collocations":{"phrases":["ADV. free, freely The animals were allowed to roam free. | about/around","VERB + ROAM allow sb/sth to, let sb/sth","PREP. over Her eyes roamed over him, assessing him. | through roaming through the town","PHRASES the freedom/right to roam Ramblers are calling for the right to roam to be made law."]},"media":{"uk":"media/ldoce/hwd/bre/d/roam0205.mp3","us":"media/ldoce/hwd/ame/5/roam.mp3"},"examples":[{"en":"The sheep are allowed to roam freely on this land.","cn":"绵羊可以在这片地上自由走动。"},{"en":"His gaze roamed over her.","cn":"他聚精会神地上下打量她。"}],"oxford":{"phon":"rəʊm","pos":"verb","senses":[{"en":"to walk or travel around an area without any definite aim or direction","cn":"徜徉；闲逛；漫步","g":"[intransitive, transitive]","ex":{"en":"The sheep are allowed to roam freely on this land.","cn":"绵羊可以在这片地上自由走动。"}},{"en":"to move slowly over every part of somebody/something","cn":"（缓慢地）扫遍，摸遍","g":"[intransitive, transitive]","ex":{"en":"His gaze roamed over her.","cn":"他聚精会神地上下打量她。"}}]}},"robe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"长袍;罩袍","en":"A robe is a loose piece of clothing which covers all of your body and reaches the ground. You can describe someone as wearing a robe or as wearing robes .","ex":{"en":"Pope John Paul II knelt in his white robes before the simple altar.","cn":"教皇约翰·保罗二世身着白色长袍在简朴的圣坛前面跪下来。"}},{"pos":"N-COUNT 可数名词","cn":"浴袍;睡袍","en":"A robe is a piece of clothing, usually made of towelling, which people wear in the house, especially when they have just got up or had a bath.","ex":{"en":"Ryle put on a robe and went down to the kitchen.","cn":"赖尔穿上睡袍，下楼去了厨房。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long loose piece of clothing, especially one worn for official ceremonies 〔","cn":"尤指正式典礼上穿的〕长袍"},{"en":"a long loose piece of clothing that you wear over your night clothes or after a bath","cn":"睡袍﹔浴衣"}]},"collocations":{"phrases":["ADJ. long | loose, voluminous | flowing a ghostly figure in flowing robes of white | rich The emperor was clad in a rich robe encrusted with","VERB + ROBE slip on","PREP. in a/the ~ an old man swathed in robes •"]},"media":{"uk":"media/ldoce/hwd/bre/f/robe0205.mp3","us":"media/ldoce/hwd/ame/d/robe1.mp3"},"examples":[{"en":"The priests were robed in black.","cn":"各司祭都穿上了黑袍。"},{"en":"cardinals in scarlet robes","cn":"身披红袍的枢机主教"}],"oxford":{"phon":"rəʊb","pos":"noun","senses":[{"en":"a long loose outer piece of clothing, especially one worn as a sign of rank or office at a special ceremony","cn":"袍服，礼袍（常于典礼中穿着以显示身份）","ex":{"en":"coronation robes","cn":"加冕礼袍"}},{"en":"a loose piece of clothing worn before and after taking a bath","cn":"浴衣；浴袍"},{"en":"a long loose piece of clothing, usually with a belt, worn indoors over night clothes, for example when you first get out of bed","cn":"晨衣，晨袍（起床后套于睡衣外在室内穿的宽松长罩衫，通常有束带）","lab":"both North American English"},{"en":"to dress somebody/yourself in long loose clothes or in the way mentioned","cn":"（给某人）穿上礼袍","ex":{"en":"a robed choir","cn":"身着礼袍的唱诗班"},"pos":"verb"}]}},"rout":{"collins":{"senses":[{"pos":"VERB 动词","cn":"击溃;大败;彻底打败","en":"If an army, sports team, or other group routs its opponents, it defeats them completely and easily.","ex":{"en":"...the Battle of Hastings at which the Norman army routed the English opposition.","cn":"诺曼军队彻底击溃英格兰军队的黑斯廷斯战役"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to completely beat someone in a game, competition, election etc","cn":""},{"en":"to beat someone very easily in a game, competition, election etc","cn":""},{"en":"to beat an opposing team or political party easily and completely","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 v","senses":[{"en":"When you think about the thrill of victory and the agony of defeat, associate a rout with the agonizing defeat. A rout is the kind of humiliating loss that makes you wish you would have been injured in the first quarter so you could have avoided the outcome."}]},"collocations":{"phrases":["ADJ. total","VERB + ROUT become, end in, turn into The game ended in a total rout. | put sb to They put the rebel army to rout. | start | complete"]},"media":{"uk":"media/ldoce/hwd/bre/2/rout_las3_br.mp3","us":"media/ldoce/hwd/ame/5/rout1.mp3"},"examples":[{"en":"The Buffalo Bills routed the Atlanta Falcons 41–14.","cn":"水牛城比尔队以 41:14 大胜亚特兰大猎鹰队。"},{"en":"The battle turned into a rout.","cn":"战斗彻底失败。"}],"oxford":{"phon":"raʊt","pos":"noun","senses":[{"en":"a situation in which somebody is defeated easily and completely in a battle or competition","cn":"溃败；彻底失败","ex":{"en":"Only the skill of the goalkeeper prevented the match from turning into a rout.","cn":"只有守门员的技术才阻止了比赛变成溃败。"}},{"en":"to defeat somebody completely in a competition, a battle, etc.","cn":"彻底击败；使溃败","ex":{"en":"The Buffalo Bills routed the Atlanta Falcons 41–14.","cn":"布法罗比尔队以 41:14 大胜亚特兰大猎鹰队。"},"pos":"verb"}]}},"rom":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"只读存储器","en":"ROM is the permanent part of a computer's memory. The information stored there can be read but not changed. ROM is an abbreviation for (缩略=) 'read-only memory'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a computer where permanent instructions and information are stored","cn":"只读存储器"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasderom.mp3","us":"media/ldoce/hwd/ame/a/rom.mp3"},"oxford":{"phon":"rɒm","pos":"noun","senses":[{"en":"computer memory that contains instructions or data that cannot be changed or removed (the abbreviation for ‘read-only memory’)","cn":"只读存储器（全写为 read-only memory）"}]}}});
